+"""RegIntel configuration loaded from environment variables.
+
+Reads two settings (per `manifest.md` / story AC7-AC8):
+
+  * ``CONFIDENCE_THRESHOLD`` — float; default 0.70. An unparseable value
+    raises ``ValueError`` naming the variable — it does NOT silently fall
+    back to the default.
+  * ``REGINTEL_DB`` — file path; default ``./regintel.db``. An empty string
+    is treated as unset (falls back to default).
+
+The module deliberately does not read ``.env``: secrets are loaded by the
+copied ``dial/client.py``. This module only consumes already-loaded
+process environment variables (``os.environ``).
+"""
+from __future__ import annotations
+
+import os
+from dataclasses import dataclass
+
+
+DEFAULT_CONFIDENCE_THRESHOLD: float = 0.70
+DEFAULT_DB_PATH: str = "./regintel.db"
+
+
+@dataclass(frozen=True)
+class Config:
+    """Resolved RegIntel runtime configuration."""
+
+    confidence_threshold: float
+    db_path: str
+
+
+def _env_nonempty(name: str) -> Optional[str]:
+    """Return ``os.environ[name]`` only if it exists AND is not empty.
+
+    An empty string (e.g. ``REGINTEL_DB=``) is treated as unset, so the
+    default kicks in instead of being silently overridden by "".
+    """
+    value = os.environ.get(name)
+    if value is None:
+        return None
+    if value.strip() == "":
+        return None
+    return value
+
+
+def load_config() -> Config:
+    """Build a :class:`Config` from the current process environment.
+
+    Raises ``ValueError`` naming the offending variable if
+    ``CONFIDENCE_THRESHOLD`` cannot be parsed as a float.
+    """
+    raw_threshold = os.environ.get("CONFIDENCE_THRESHOLD")
+    if raw_threshold is not None and raw_threshold.strip() != "":
+        try:
+            threshold = float(raw_threshold)
+        except ValueError as exc:
+            raise ValueError(
+                f"CONFIDENCE_THRESHOLD={raw_threshold!r} is not a valid float"
+            ) from exc
+    else:
+        threshold = DEFAULT_CONFIDENCE_THRESHOLD
+
+    db_path = _env_nonempty("REGINTEL_DB") or DEFAULT_DB_PATH
+
+    return Config(confidence_threshold=threshold, db_path=db_path)
+
+
+__all__ = [
+    "Config",
+    "DEFAULT_CONFIDENCE_THRESHOLD",
+    "DEFAULT_DB_PATH",
+    "load_config",
+]
