+"""Data model dataclasses for RegIntel Studio.
+
+The fields below are the source of truth from `manifest.md` "Data Model":
+
+- EventRecord fields: event_id, source_id, source_name, source_type,
+  source_reliability, jurisdiction_level, jurisdiction_name, detected_at,
+  effective_date, is_pending_legislation, raw_text, content_hash,
+  injection_suspected, created_at
+- ClassificationRecord fields: event_id, bucket, proposed_bucket, confidence,
+  rationale, topic_tags, duplicate_of, model, prompt_version, prompt_tokens,
+  completion_tokens, cost_usd, raw_model_output, classified_at
+- ReviewRecord fields: event_id, reviewer, action, final_bucket,
+  reviewer_rationale, reviewed_at
+
+`Optional[...]` is used for nullable columns identified in the manifest
+(effective_date) and for values populated later (created_at, classified_at,
+reviewed_at). All other columns are required.
+"""
+from __future__ import annotations
+
+from dataclasses import dataclass, field
+from datetime import datetime
+from typing import List, Optional
+
+
+@dataclass
+class EventRecord:
+    """One per ingested regulatory update."""
+
+    event_id: str
+    source_id: str
+    source_name: str
+    source_type: str
+    source_reliability: str
+    jurisdiction_level: str
+    jurisdiction_name: str
+    detected_at: str
+    effective_date: Optional[str]
+    is_pending_legislation: bool
+    raw_text: str
+    content_hash: str
+    injection_suspected: bool
+    created_at: Optional[str] = None
+
+
+@dataclass
+class ClassificationRecord:
+    """One per classification; re-classification appends, never overwrites."""
+
+    event_id: str
+    bucket: str
+    proposed_bucket: str
+    confidence: float
+    rationale: str
+    topic_tags: List[str]
+    duplicate_of: Optional[str]
+    model: str
+    prompt_version: str
+    prompt_tokens: int
+    completion_tokens: int
+    cost_usd: float
+    raw_model_output: str
+    classified_at: Optional[str] = None
+
+
+@dataclass
+class ReviewRecord:
+    """One per human reviewer action."""
+
+    event_id: str
+    reviewer: str
+    action: str
+    final_bucket: str
+    reviewer_rationale: str
+    reviewed_at: Optional[str] = None
+
+
+def utc_now_iso() -> str:
+    """Return the current UTC time as an ISO-8601 string.
+
+    Centralised so every persisted ``*_at`` column uses an identical format
+    and the store has a single place to swap timestamp logic if needed.
+    """
+    return datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
+
+
+__all__ = [
+    "EventRecord",
+    "ClassificationRecord",
+    "ReviewRecord",
+    "utc_now_iso",
+]
