+"""SQLite-backed persistence for RegIntel Studio.
+
+Built on stdlib ``sqlite3`` only — no ORM, no third-party DB driver. Three
+tables:
+
+  * ``events`` — one row per ingested update (mutated only by insert/get/list)
+  * ``classifications`` — append-only audit log of model outputs
+  * ``reviews`` — append-only audit log of human reviewer actions
+
+Mutability contract (enforced by absence of any UPDATE/DELETE against the
+two append-only tables in this module):
+
+  * ``classifications`` rows are only ever INSERTED. ``append_classification``
+    is the sole writer; there is no update or delete function for the table.
+  * ``reviews`` rows are only ever INSERTED. ``append_review`` is the sole
+    writer; there is no update or delete function for the table.
+
+This makes the review trail immutable from the application's perspective —
+the only way to "change" a decision is to record a new review row pointing
+at the same event.
+"""
+from __future__ import annotations
+
+import json
+import sqlite3
+from pathlib import Path
+from typing import Iterable, List, Optional
+
+from regintel.models import (
+    ClassificationRecord,
+    EventRecord,
+    ReviewRecord,
+    utc_now_iso,
+)
+
+
+# ---------------------------------------------------------------------------
+# Schema
+# ---------------------------------------------------------------------------
+
+SCHEMA_STATEMENTS: tuple[str, ...] = (
+    """
+    CREATE TABLE IF NOT EXISTS events (
+        event_id              TEXT PRIMARY KEY,
+        source_id             TEXT NOT NULL,
+        source_name           TEXT NOT NULL,
+        source_type           TEXT NOT NULL,
+        source_reliability    TEXT NOT NULL,
+        jurisdiction_level    TEXT NOT NULL,
+        jurisdiction_name     TEXT NOT NULL,
+        detected_at           TEXT NOT NULL,
+        effective_date        TEXT,
+        is_pending_legislation INTEGER NOT NULL,
+        raw_text              TEXT NOT NULL,
+        content_hash          TEXT NOT NULL,
+        injection_suspected   INTEGER NOT NULL,
+        created_at            TEXT NOT NULL
+    )
+    """,
+    """
+    CREATE TABLE IF NOT EXISTS classifications (
+        id                 INTEGER PRIMARY KEY AUTOINCREMENT,
+        event_id           TEXT NOT NULL,
+        bucket             TEXT NOT NULL,
+        proposed_bucket    TEXT NOT NULL,
+        confidence         REAL NOT NULL,
+        rationale          TEXT NOT NULL,
+        topic_tags         TEXT NOT NULL,
+        duplicate_of       TEXT,
+        model              TEXT NOT NULL,
+        prompt_version     TEXT NOT NULL,
+        prompt_tokens      INTEGER NOT NULL,
+        completion_tokens  INTEGER NOT NULL,
+        cost_usd           REAL NOT NULL,
+        raw_model_output   TEXT NOT NULL,
+        classified_at      TEXT NOT NULL,
+        FOREIGN KEY (event_id) REFERENCES events(event_id)
+    )
+    """,
+    """
+    CREATE TABLE IF NOT EXISTS reviews (
+        id                 INTEGER PRIMARY KEY AUTOINCREMENT,
+        event_id           TEXT NOT NULL,
+        reviewer           TEXT NOT NULL,
+        action             TEXT NOT NULL,
+        final_bucket       TEXT NOT NULL,
+        reviewer_rationale TEXT NOT NULL,
+        reviewed_at        TEXT NOT NULL,
+        FOREIGN KEY (event_id) REFERENCES events(event_id)
+    )
+    """,
+    "CREATE INDEX IF NOT EXISTS idx_classifications_event ON classifications(event_id)",
+    "CREATE INDEX IF NOT EXISTS idx_reviews_event ON reviews(event_id)",
+)
+
+
+# ---------------------------------------------------------------------------
+# Connection helpers
+# ---------------------------------------------------------------------------
+
+def _connect(db_path: str) -> sqlite3.Connection:
+    """Open a SQLite connection with row factory + FK enforcement."""
+    conn = sqlite3.connect(db_path)
+    conn.row_factory = sqlite3.Row
+    conn.execute("PRAGMA foreign_keys = ON")
+    return conn
+
+
+def init_db(db_path: str) -> sqlite3.Connection:
+    """Create tables (if missing) and return an open connection.
+
+    Idempotent: re-running on an initialised database is a no-op for the
+    schema, so the same path may be opened repeatedly by tests and the
+    application alike.
+    """
+    # Ensure parent directory exists so a fresh ``./regintel.db`` works.
+    parent = Path(db_path).expanduser().parent
+    if str(parent) and not parent.exists():
+        parent.mkdir(parents=True, exist_ok=True)
+
+    conn = _connect(db_path)
+    try:
+        for stmt in SCHEMA_STATEMENTS:
+            conn.execute(stmt)
+        conn.commit()
+    except Exception:
+        conn.close()
+        raise
+    return conn
+
+
+# ---------------------------------------------------------------------------
+# Row <-> dataclass helpers
+# ---------------------------------------------------------------------------
+
+_EVENT_COLUMNS = (
+    "event_id",
+    "source_id",
+    "source_name",
+    "source_type",
+    "source_reliability",
+    "jurisdiction_level",
+    "jurisdiction_name",
+    "detected_at",
+    "effective_date",
+    "is_pending_legislation",
+    "raw_text",
+    "content_hash",
+    "injection_suspected",
+    "created_at",
+)
+
+
+def _row_to_event(row: sqlite3.Row) -> EventRecord:
+    return EventRecord(
+        event_id=row["event_id"],
+        source_id=row["source_id"],
+        source_name=row["source_name"],
+        source_type=row["source_type"],
+        source_reliability=row["source_reliability"],
+        jurisdiction_level=row["jurisdiction_level"],
+        jurisdiction_name=row["jurisdiction_name"],
+        detected_at=row["detected_at"],
+        effective_date=row["effective_date"],
+        is_pending_legislation=bool(row["is_pending_legislation"]),
+        raw_text=row["raw_text"],
+        content_hash=row["content_hash"],
+        injection_suspected=bool(row["injection_suspected"]),
+        created_at=row["created_at"],
+    )
+
+
+def _row_to_classification(row: sqlite3.Row) -> ClassificationRecord:
+    tags_raw = row["topic_tags"]
+    try:
+        tags = json.loads(tags_raw) if tags_raw else []
+    except json.JSONDecodeError:
+        # Defensive: tolerate legacy / corrupted rows without crashing.
+        tags = []
+    if not isinstance(tags, list):
+        tags = [str(tags)]
+    return ClassificationRecord(
+        event_id=row["event_id"],
+        bucket=row["bucket"],
+        proposed_bucket=row["proposed_bucket"],
+        confidence=float(row["confidence"]),
+        rationale=row["rationale"],
+        topic_tags=[str(t) for t in tags],
+        duplicate_of=row["duplicate_of"],
+        model=row["model"],
+        prompt_version=row["prompt_version"],
+        prompt_tokens=int(row["prompt_tokens"]),
+        completion_tokens=int(row["completion_tokens"]),
+        cost_usd=float(row["cost_usd"]),
+        raw_model_output=row["raw_model_output"],
+        classified_at=row["classified_at"],
+    )
+
+
+def _row_to_review(row: sqlite3.Row) -> ReviewRecord:
+    return ReviewRecord(
+        event_id=row["event_id"],
+        reviewer=row["reviewer"],
+        action=row["action"],
+        final_bucket=row["final_bucket"],
+        reviewer_rationale=row["reviewer_rationale"],
+        reviewed_at=row["reviewed_at"],
+    )
+
+
+# ---------------------------------------------------------------------------
+# Events
+# ---------------------------------------------------------------------------
+
+def insert_event(conn: sqlite3.Connection, record: EventRecord) -> EventRecord:
+    """Insert an event row. Sets ``created_at`` if not already populated.
+
+    The caller is expected to provide a stable ``event_id`` derived from
+    source + detected date + content hash (per manifest.md). Inserting a
+    duplicate ``event_id`` raises ``sqlite3.IntegrityError`` so the caller
+    can decide whether to swallow it (idempotent ingest) or surface it.
+    """
+    created_at = record.created_at or utc_now_iso()
+    conn.execute(
+        """
+        INSERT INTO events (
+            event_id, source_id, source_name, source_type, source_reliability,
+            jurisdiction_level, jurisdiction_name, detected_at, effective_date,
+            is_pending_legislation, raw_text, content_hash, injection_suspected,
+            created_at
+        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
+        """,
+        (
+            record.event_id,
+            record.source_id,
+            record.source_name,
+            record.source_type,
+            record.source_reliability,
+            record.jurisdiction_level,
+            record.jurisdiction_name,
+            record.detected_at,
+            record.effective_date,
+            1 if record.is_pending_legislation else 0,
+            record.raw_text,
+            record.content_hash,
+            1 if record.injection_suspected else 0,
+            created_at,
+        ),
+    )
+    conn.commit()
+    return EventRecord(
+        event_id=record.event_id,
+        source_id=record.source_id,
+        source_name=record.source_name,
+        source_type=record.source_type,
+        source_reliability=record.source_reliability,
+        jurisdiction_level=record.jurisdiction_level,
+        jurisdiction_name=record.jurisdiction_name,
+        detected_at=record.detected_at,
+        effective_date=record.effective_date,
+        is_pending_legislation=record.is_pending_legislation,
+        raw_text=record.raw_text,
+        content_hash=record.content_hash,
+        injection_suspected=record.injection_suspected,
+        created_at=created_at,
+    )
+
+
+def get_event(conn: sqlite3.Connection, event_id: str) -> Optional[EventRecord]:
+    """Return the event with the given id, or ``None`` if not present.
+
+    Always returns an absence indicator rather than raising for unknown
+    ids — matches AC9.
+    """
+    row = conn.execute(
+        f"SELECT {_col_list(_EVENT_COLUMNS)} FROM events WHERE event_id = ?",
+        (event_id,),
+    ).fetchone()
+    return _row_to_event(row) if row is not None else None
+
+
+def list_events(conn: sqlite3.Connection) -> List[EventRecord]:
+    """Return all events ordered by ``detected_at``, then ``event_id``.
+
+    On an empty / freshly initialised database this returns ``[]`` rather
+    than raising — matches AC9.
+    """
+    rows = conn.execute(
+        f"SELECT {_col_list(_EVENT_COLUMNS)} FROM events "
+        "ORDER BY detected_at ASC, event_id ASC"
+    ).fetchall()
+    return [_row_to_event(r) for r in rows]
+
+
+def _col_list(cols: Iterable[str]) -> str:
+    return ", ".join(cols)
+
+
+# ---------------------------------------------------------------------------
+# Classifications (append-only)
+# ---------------------------------------------------------------------------
+
+def append_classification(
+    conn: sqlite3.Connection, record: ClassificationRecord
+) -> ClassificationRecord:
+    """Append a classification row. Never modifies an existing row.
+
+    ``classified_at`` is populated with the current UTC time if the caller
+    didn't supply one.
+    """
+    classified_at = record.classified_at or utc_now_iso()
+    tags_json = json.dumps(list(record.topic_tags))
+    conn.execute(
+        """
+        INSERT INTO classifications (
+            event_id, bucket, proposed_bucket, confidence, rationale,
+            topic_tags, duplicate_of, model, prompt_version,
+            prompt_tokens, completion_tokens, cost_usd, raw_model_output,
+            classified_at
+        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
+        """,
+        (
+            record.event_id,
+            record.bucket,
+            record.proposed_bucket,
+            record.confidence,
+            record.rationale,
+            tags_json,
+            record.duplicate_of,
+            record.model,
+            record.prompt_version,
+            record.prompt_tokens,
+            record.completion_tokens,
+            record.cost_usd,
+            record.raw_model_output,
+            classified_at,
+        ),
+    )
+    conn.commit()
+    return ClassificationRecord(
+        event_id=record.event_id,
+        bucket=record.bucket,
+        proposed_bucket=record.proposed_bucket,
+        confidence=record.confidence,
+        rationale=record.rationale,
+        topic_tags=list(record.topic_tags),
+        duplicate_of=record.duplicate_of,
+        model=record.model,
+        prompt_version=record.prompt_version,
+        prompt_tokens=record.prompt_tokens,
+        completion_tokens=record.completion_tokens,
+        cost_usd=record.cost_usd,
+        raw_model_output=record.raw_model_output,
+        classified_at=classified_at,
+    )
+
+
+def latest_classification(
+    conn: sqlite3.Connection, event_id: str
+) -> Optional[ClassificationRecord]:
+    """Return the most recent classification for an event, or ``None``.
+
+    "Most recent" is the row with the highest auto-incrementing ``id``
+    (insertion order), which is monotonic and stable even when several
+    classifications share a ``classified_at`` second.
+
+    Returns ``None`` rather than raising when no classification exists yet
+    — matches AC9.
+    """
+    row = conn.execute(
+        """
+        SELECT event_id, bucket, proposed_bucket, confidence, rationale,
+               topic_tags, duplicate_of, model, prompt_version,
+               prompt_tokens, completion_tokens, cost_usd, raw_model_output,
+               classified_at
+        FROM classifications
+        WHERE event_id = ?
+        ORDER BY id DESC
+        LIMIT 1
+        """,
+        (event_id,),
+    ).fetchone()
+    return _row_to_classification(row) if row is not None else None
+
+
+def list_classifications(
+    conn: sqlite3.Connection, event_id: str
+) -> List[ClassificationRecord]:
+    """Return every classification row for an event, oldest first."""
+    rows = conn.execute(
+        """
+        SELECT event_id, bucket, proposed_bucket, confidence, rationale,
+               topic_tags, duplicate_of, model, prompt_version,
+               prompt_tokens, completion_tokens, cost_usd, raw_model_output,
+               classified_at
+        FROM classifications
+        WHERE event_id = ?
+        ORDER BY id ASC
+        """,
+        (event_id,),
+    ).fetchall()
+    return [_row_to_classification(r) for r in rows]
+
+
+# ---------------------------------------------------------------------------
+# Reviews (append-only)
+# ---------------------------------------------------------------------------
+
+def append_review(conn: sqlite3.Connection, record: ReviewRecord) -> ReviewRecord:
+    """Append a review row. Never modifies an existing row."""
+    reviewed_at = record.reviewed_at or utc_now_iso()
+    conn.execute(
+        """
+        INSERT INTO reviews (
+            event_id, reviewer, action, final_bucket,
+            reviewer_rationale, reviewed_at
+        ) VALUES (?, ?, ?, ?, ?, ?)
+        """,
+        (
+            record.event_id,
+            record.reviewer,
+            record.action,
+            record.final_bucket,
+            record.reviewer_rationale,
+            reviewed_at,
+        ),
+    )
+    conn.commit()
+    return ReviewRecord(
+        event_id=record.event_id,
+        reviewer=record.reviewer,
+        action=record.action,
+        final_bucket=record.final_bucket,
+        reviewer_rationale=record.reviewer_rationale,
+        reviewed_at=reviewed_at,
+    )
+
+
+def list_reviews(conn: sqlite3.Connection, event_id: str) -> List[ReviewRecord]:
+    """Return every review row for an event, oldest first."""
+    rows = conn.execute(
+        """
+        SELECT event_id, reviewer, action, final_bucket,
+               reviewer_rationale, reviewed_at
+        FROM reviews
+        WHERE event_id = ?
+        ORDER BY id ASC
+        """,
+        (event_id,),
+    ).fetchall()
+    return [_row_to_review(r) for r in rows]
+
+
+__all__ = [
+    "init_db",
+    "insert_event",
+    "get_event",
+    "list_events",
+    "append_classification",
+    "latest_classification",
+    "list_classifications",
+    "append_review",
+    "list_reviews",
+    "SCHEMA_STATEMENTS",
+]
