+
+        .btn-override {
+            background: #ff9800;
+            color: white;
+        }
+
+        .btn-override:hover {
+            background: #e68900;
+        }
+
+        .modal {
+            display: none;
+            position: fixed;
+            z-index: 1000;
+            left: 0;
+            top: 0;
+            width: 100%;
+            height: 100%;
+            background-color: rgba(0, 0, 0, 0.5);
+            animation: fadeIn 0.2s ease-in;
+        }
+
+        @keyframes fadeIn {
+            from { opacity: 0; }
+            to { opacity: 1; }
+        }
+
+        .modal-content {
+            background: white;
+            margin: 5% auto;
+            padding: 20px;
+            border-radius: 8px;
+            width: 90%;
+            max-width: 500px;
+            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
+            animation: slideDown 0.2s ease-out;
+        }
+
+        @keyframes slideDown {
+            from { transform: translateY(-50px); opacity: 0; }
+            to { transform: translateY(0); opacity: 1; }
+        }
+
+        .modal-header {
+            font-size: 18px;
+            font-weight: 600;
+            margin-bottom: 15px;
+        }
+
+        .modal-body {
+            margin-bottom: 20px;
+        }
+
+        .form-group {
+            margin-bottom: 15px;
+        }
+
+        .form-group label {
+            display: block;
+            margin-bottom: 5px;
+            font-weight: 500;
+        }
+
+        .form-group input,
+        .form-group select,
+        .form-group textarea {
+            width: 100%;
+            padding: 8px;
+            border: 1px solid #ccc;
+            border-radius: 4px;
+            font-size: 14px;
+            font-family: inherit;
+        }
+
+        .form-group textarea {
+            resize: vertical;
+            min-height: 80px;
+        }
+
+        .modal-footer {
+            display: flex;
+            gap: 10px;
+            justify-content: flex-end;
+        }
+
+        .btn-primary {
+            background: #1976d2;
+            color: white;
+        }
+
+        .btn-primary:hover {
+            background: #1565c0;
+        }
+
+        .btn-primary:disabled {
+            background: #ccc;
+            cursor: not-allowed;
+        }
+
+        .btn-cancel {
+            background: #f5f5f5;
+            color: #333;
+            border: 1px solid #ccc;
+        }
+
+        .btn-cancel:hover {
+            background: #e8e8e8;
+        }
+
+        .loading {
+            text-align: center;
+            padding: 40px;
+            color: #666;
+        }
+
+        .spinner {
+            border: 3px solid #f3f3f3;
+            border-top: 3px solid #1976d2;
+            border-radius: 50%;
+            width: 40px;
+            height: 40px;
+            animation: spin 1s linear infinite;
+            margin: 0 auto 15px;
+        }
+
+        @keyframes spin {
+            0% { transform: rotate(0deg); }
+            100% { transform: rotate(360deg); }
+        }
+
+        .success-message {
+            background: #e8f5e9;
+            color: #2e7d32;
+            padding: 12px;
+            border-radius: 4px;
+            margin-bottom: 15px;
+        }
+
+        .status-badge {
+            display: inline-block;
+            padding: 4px 8px;
+            border-radius: 4px;
+            font-size: 12px;
+            font-weight: 500;
+            background: #e0e0e0;
+            color: #333;
+        }
+
+        .status-pending {
+            background: #fff3e0;
+            color: #e65100;
+        }
+
+        .status-confirmed {
+            background: #e8f5e9;
+            color: #2e7d32;
+        }
+
+        .status-overridden {
+            background: #e3f2fd;
+            color: #1565c0;
+        }
+    </style>
+</head>
+<body>
+    <div class="container">
+        <header>
+            <h1>Review Portal</h1>
+            <div class="metrics-strip" id="metrics"></div>
+        </header>
+
+        <div class="controls">
+            <div class="filter-group">
+                <label for="bucket-filter">Filter by bucket:</label>
+                <select id="bucket-filter">
+                    <option value="all">all</option>
+                    <option value="relevant">relevant</option>
+                    <option value="irrelevant">irrelevant</option>
+                    <option value="duplicate">duplicate</option>
+                    <option value="needs-review">needs-review</option>
+                </select>
+            </div>
+        </div>
+
+        <div id="error-container"></div>
+        <div id="table-container"></div>
+    </div>
+
+    <div id="override-modal" class="modal">
+        <div class="modal-content">
+            <div class="modal-header">Override Review Decision</div>
+            <div class="modal-body">
+                <div class="form-group">
+                    <label for="override-bucket">Bucket:</label>
+                    <select id="override-bucket">
+                        <option value="">-- Select bucket --</option>
+                        <option value="relevant">relevant</option>
+                        <option value="irrelevant">irrelevant</option>
+                        <option value="duplicate">duplicate</option>
+                        <option value="needs-review">needs-review</option>
+                    </select>
+                </div>
+                <div class="form-group">
+                    <label for="override-reviewer">Reviewer:</label>
+                    <input type="text" id="override-reviewer" placeholder="Enter reviewer name">
+                </div>
+                <div class="form-group">
+                    <label for="override-rationale">Rationale:</label>
+                    <textarea id="override-rationale" placeholder="Enter rationale for this decision"></textarea>
+                </div>
+            </div>
+            <div class="modal-footer">
+                <button class="btn-cancel" id="modal-cancel">Cancel</button>
+                <button class="btn-primary" id="override-submit">Submit Override</button>
+            </div>
+        </div>
+    </div>
+
+    <script>
+        let allData = [];
+        let currentFilter = "all";
+        let currentOverrideEventId = null;
+
+        async function fetchQueue() {
+            try {
+                const response = await fetch('/queue');
+                if (!response.ok) {
+                    throw new Error(`HTTP error! status: ${response.status}`);
+                }
+                return await response.json();
+            } catch (error) {
+                console.error('Error fetching queue:', error);
+                showError('Failed to fetch review queue. Please try again.');
+                return null;
+            }
+        }
+
+        async function fetchMetrics() {
+            try {
+                const response = await fetch('/metrics');
+                if (!response.ok) {
+                    throw new Error(`HTTP error! status: ${response.status}`);
+                }
+                return await response.json();
+            } catch (error) {
+                console.error('Error fetching metrics:', error);
+                return null;
+            }
+        }
+
+        function showError(message) {
+            const container = document.getElementById('error-container');
+            container.innerHTML = `<div class="error-state">${escapeHtml(message)}</div>`;
+        }
+
+        function renderMetrics(metrics) {
+            if (!metrics) {
+                return;
+            }
+
+            const container = document.getElementById('metrics');
+            const bucketCounts = metrics.bucket_counts || {};
+            const costPerEvent = metrics.cost_per_event_usd || 0;
+
+            let html = '';
+            for (const [bucket, count] of Object.entries(bucketCounts)) {
+                html += `
+                    <div class="metric-item">
+                        <div class="metric-label">${escapeHtml(bucket)}</div>
+                        <div class="metric-value">${count}</div>
+                    </div>
+                `;
+            }
+
+            html += `
+                <div class="metric-item">
+                    <div class="metric-label">Cost per Event</div>
+                    <div class="metric-value">$${costPerEvent.toFixed(4)}</div>
+                </div>
+            `;
+
+            container.innerHTML = html;
+        }
+
+        function escapeHtml(text) {
+            const map = {
+                '&': '&amp;',
+                '<': '&lt;',
+                '>': '&gt;',
+                '"': '&quot;',
+                "'": '&#039;'
+            };
+            return String(text).replace(/[&<>"']/g, m => map[m]);
+        }
+
+        function getBucketColor(bucket) {
+            const colors = {
+                'relevant': '#4caf50',
+                'irrelevant': '#9e9e9e',
+                'duplicate': '#2196f3',
+                'needs-review': '#ff9800'
+            };
+            return colors[bucket] || '#999';
+        }
+
+        function getBucketIcon(bucket) {
+            const icons = {
+                'relevant': '✓',
+                'irrelevant': '✗',
+                'duplicate': '◊',
+                'needs-review': '!'
+            };
+            return icons[bucket] || '•';
+        }
+
+        function getBucketClass(bucket) {
+            const classes = {
+                'relevant': 'bucket-relevant',
+                'irrelevant': 'bucket-irrelevant',
+                'duplicate': 'bucket-duplicate',
+                'needs-review': 'bucket-needs-review'
+            };
+            return classes[bucket] || '';
+        }
+
+        function getStatusClass(status) {
+            const classes = {
+                'pending': 'status-pending',
+                'confirmed': 'status-confirmed',
+                'overridden': 'status-overridden'
+            };
+            return classes[status] || '';
+        }
+
+        function truncateText(text, maxLength = 100) {
+            if (text.length <= maxLength) {
+                return text;
+            }
+            return text.substring(0, maxLength) + '...';
+        }
+
+        function toggleRationale(eventId) {
+            const selector = '[data-rationale-text="' + eventId + '"]';
+            const rationaleText = document.querySelector(selector);
+            if (rationaleText) {
+                rationaleText.classList.toggle('rationale-expanded');
+                const toggleSelector = '[data-toggle="' + eventId + '"]';
+                const toggle = document.querySelector(toggleSelector);
+                if (toggle) {
+                    toggle.textContent = rationaleText.classList.contains('rationale-expanded') ? 'Show less' : 'Show more';
+                }
+            }
+        }
+
+        async function approveReview(eventId) {
+            try {
+                const response = await fetch('/events/' + eventId + '/review', {
+                    method: 'POST',
+                    headers: {
+                        'Content-Type': 'application/json'
+                    },
+                    body: JSON.stringify({
+                        action: 'confirm',
+                        final_bucket: 'relevant',
+                        reviewer: 'Auto',
+                        reviewer_rationale: 'Approved via portal'
+                    })
+                });
+
+                if (!response.ok) {
+                    throw new Error('HTTP error! status: ' + response.status);
+                }
+
+                const result = await response.json();
+                updateRowAfterReview(eventId, result.final_bucket, result.action);
+            } catch (error) {
+                console.error('Error approving review:', error);
+                alert('Failed to submit approval. Please try again.');
+            }
+        }
+
+        function openOverrideModal(eventId) {
+            currentOverrideEventId = eventId;
+            document.getElementById('override-modal').style.display = 'block';
+            document.getElementById('override-bucket').value = '';
+            document.getElementById('override-reviewer').value = '';
+            document.getElementById('override-rationale').value = '';
+        }
+
+        function closeOverrideModal() {
+            document.getElementById('override-modal').style.display = 'none';
+            currentOverrideEventId = null;
+        }
+
+        async function submitOverride() {
+            const bucket = document.getElementById('override-bucket').value;
+            const reviewer = document.getElementById('override-reviewer').value;
+            const rationale = document.getElementById('override-rationale').value;
+
+            if (!bucket) {
+                alert('Please select a bucket');
+                return;
+            }
+            if (!reviewer) {
+                alert('Please enter reviewer name');
+                return;
+            }
+            if (!rationale) {
+                alert('Please enter rationale');
+                return;
+            }
+
+            try {
+                const response = await fetch(`/events/${currentOverrideEventId}/review`, {
+                    method: 'POST',
+                    headers: {
+                        'Content-Type': 'application/json'
+                    },
+                    body: JSON.stringify({
+                        action: 'override',
+                        final_bucket: bucket,
+                        reviewer: reviewer,
+                        reviewer_rationale: rationale
+                    })
+                });
+
+                if (!response.ok) {
+                    throw new Error(`HTTP error! status: ${response.status}`);
+                }
+
+                const result = await response.json();
+                updateRowAfterReview(currentOverrideEventId, result.final_bucket, result.action);
+                closeOverrideModal();
+            } catch (error) {
+                console.error('Error submitting override:', error);
+                alert('Failed to submit override. Please try again.');
+            }
+        }
+
+        function updateRowAfterReview(eventId, finalBucket, action) {
+            const item = allData.find(d => d.event_id === eventId);
+            if (item) {
+                item.bucket = finalBucket;
+                item.review_status = action === 'confirm' ? 'confirmed' : 'overridden';
+                renderTable(allData);
+            }
+        }
+
+        window.onclick = function(event) {
+            const modal = document.getElementById('override-modal');
+            if (event.target === modal) {
+                closeOverrideModal();
+            }
+        };
+
+        function renderTable(data) {
+            const container = document.getElementById('table-container');
+
+            if (data.length === 0) {
+                container.innerHTML = '<div class="empty-state">When the review queue contains zero items, the table renders with an explicit empty-state message rather than erroring or rendering a blank area.</div>';
+                return;
+            }
+
+            let html = `
+                <div class="table-wrapper">
+                    <table>
+                        <thead>
+                            <tr>
+                                <th>Source ID</th>
+                                <th>Jurisdiction</th>
+                                <th>Detected Timestamp</th>
+                                <th>Bucket</th>
+                                <th>Confidence</th>
+                                <th>Injection Flag</th>
+                                <th>Rationale</th>
+                                <th>Review Status</th>
+                                <th>Actions</th>
+                            </tr>
+                        </thead>
+                        <tbody>
+            `;
+
+            for (const item of data) {
+                if (currentFilter !== 'all' && item.bucket !== currentFilter) {
+                    continue;
+                }
+
+                const bucketBadgeClass = getBucketClass(item.bucket);
+                const bucketIcon = getBucketIcon(item.bucket);
+                const statusClass = getStatusClass(item.review_status);
+                const rationalePreview = truncateText(item.rationale, 100);
+                const showExpandBtn = item.rationale.length > 100;
+                const eventIdAttr = item.event_id.replace(/"/g, '&quot;');
+
+                html += `
+                    <tr data-event-id="${eventIdAttr}">
+                        <td>${escapeHtml(item.source_id)}</td>
+                        <td>${escapeHtml(item.jurisdiction)}</td>
+                        <td>${escapeHtml(item.detected_timestamp)}</td>
+                        <td>
+                            <div class="bucket-cell">
+                                <span class="bucket-badge ${bucketBadgeClass}">
+                                    <span class="badge-icon">${bucketIcon}</span>
+                                    ${escapeHtml(item.bucket)}
+                                </span>
+                            </div>
+                        </td>
+                        <td>${item.confidence !== null ? (item.confidence * 100).toFixed(1) + '%' : 'N/A'}</td>
+                        <td>${item.injection_flag ? 'Yes' : 'No'}</td>
+                        <td>
+                            <div class="rationale-cell">
+                                <div class="rationale-text" data-rationale-text="${eventIdAttr}">
+                                    ${escapeHtml(rationalePreview)}
+                                </div>
+                                ${showExpandBtn ? `<button class="expand-toggle" data-toggle="${eventIdAttr}">Show more</button>` : ''}
+                            </div>
+                        </td>
+                        <td>
+                            <span class="status-badge ${statusClass}">${escapeHtml(item.review_status)}</span>
+                        </td>
+                        <td>
+                            <div class="actions-cell">
+                                <button class="btn-approve" data-action="approve">Approve</button>
+                                <button class="btn-override" data-action="override">Override</button>
+                            </div>
+                        </td>
+                    </tr>
+                `;
+            }
+
+            html += `
+                        </tbody>
+                    </table>
+                </div>
+            `;
+
+            container.innerHTML = html;
+            attachTableListeners();
+        }
+
+        function attachTableListeners() {
+            document.querySelectorAll('[data-toggle]').forEach(btn => {
+                btn.addEventListener('click', function(e) {
+                    e.preventDefault();
+                    const eventId = this.getAttribute('data-toggle');
+                    toggleRationale(eventId);
+                });
+            });
+
+            document.querySelectorAll('[data-action="approve"]').forEach(btn => {
+                btn.addEventListener('click', function(e) {
+                    e.preventDefault();
+                    const eventId = this.closest('tr').getAttribute('data-event-id');
+                    approveReview(eventId);
+                });
+            });
+
+            document.querySelectorAll('[data-action="override"]').forEach(btn => {
+                btn.addEventListener('click', function(e) {
+                    e.preventDefault();
+                    const eventId = this.closest('tr').getAttribute('data-event-id');
+                    openOverrideModal(eventId);
+                });
+            });
+        }
+
+        async function init() {
+            const container = document.getElementById('table-container');
+            container.innerHTML = '<div class="loading"><div class="spinner"></div>Loading review queue...</div>';
+
+            const queue = await fetchQueue();
+            const metrics = await fetchMetrics();
+
+            renderMetrics(metrics);
+
+            if (queue === null) {
+                return;
+            }
+
+            allData = queue;
+            renderTable(allData);
+        }
+
+        document.getElementById('bucket-filter').addEventListener('change', (e) => {
+            currentFilter = e.target.value;
+            renderTable(allData);
+        });
+
+        document.getElementById('modal-cancel').addEventListener('click', closeOverrideModal);
+        document.getElementById('override-submit').addEventListener('click', submitOverride);
+
+        window.addEventListener('DOMContentLoaded', init);
+    </script>
+</body>
+</html>

