+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="utf-8" />
+<meta name="viewport" content="width=device-width, initial-scale=1" />
+<title>Delivery Toolkit Map</title>
+<style>
+  :root {
+    --paper: #f1f4f1;
+    --ink: #142420;
+    --ink-soft: #43534d;
