+<script>
+  const DATA = JSON.parse(document.getElementById("tool-data").textContent);
+  const PHASE_COLORS = {
+    backlog: { color: "var(--phase-1)", bg: "var(--phase-1-bg)" },
+    proposal: { color: "var(--phase-2)", bg: "var(--phase-2-bg)" },
+    prototype: { color: "var(--phase-3)", bg: "var(--phase-3-bg)" },
+    readout: { color: "var(--phase-4)", bg: "var(--phase-4-bg)" }
+  };
+  const PHASES = Object.fromEntries(
+    Object.entries(DATA.phases).map(([key, p]) => [key, { ...p, ...PHASE_COLORS[key] }])
+  );
+  const TOOLS = DATA.tools;
+
+  const state = { query: "", phases: new Set(), category: "all" };
+
+  function buildLegend() {
+    const legend = document.getElementById("legend");
+    legend.innerHTML = Object.values(PHASES).map(p =>
+      `<span class="legend-item"><span class="legend-dot" style="background:${p.color}"></span>${p.label}</span>`
+    ).join("");
+  }
+
+  function buildPhaseChips() {
+    const row = document.getElementById("phase-chips");
+    Object.entries(PHASES).forEach(([key, p]) => {
+      const btn = document.createElement("button");
+      btn.className = "chip";
+      btn.type = "button";
+      btn.setAttribute("aria-pressed", "false");
+      btn.dataset.phase = key;
+      btn.innerHTML = `<span class="dot" style="background:${p.color}"></span>${p.label}`;
+      btn.addEventListener("click", () => {
+        if (state.phases.has(key)) state.phases.delete(key);
+        else state.phases.add(key);
+        btn.setAttribute("aria-pressed", String(state.phases.has(key)));
+        render();
+      });
+      row.appendChild(btn);
+    });
+  }
+
+  function buildCategoryChips() {
+    const row = document.getElementById("category-chips");
+    const categories = ["all", ...new Set(TOOLS.map(t => t.category))];
+    categories.forEach(cat => {
+      const btn = document.createElement("button");
+      btn.className = "chip";
+      btn.type = "button";
+      btn.textContent = cat === "all" ? "All" : cat;
+      btn.setAttribute("aria-pressed", String(cat === "all"));
+      btn.dataset.category = cat;
+      btn.addEventListener("click", () => {
+        state.category = cat;
+        row.querySelectorAll(".chip").forEach(c =>
+          c.setAttribute("aria-pressed", String(c.dataset.category === cat))
+        );
+        render();
+      });
+      row.appendChild(btn);
+    });
+  }
+
+  function matches(tool) {
+    const q = state.query.trim().toLowerCase();
+    const textOk = !q || [tool.name, tool.blurb, tool.category].join(" ").toLowerCase().includes(q);
+    const phaseOk = state.phases.size === 0 || tool.phases.some(p => state.phases.has(p));
+    const catOk = state.category === "all" || tool.category === state.category;
+    return textOk && phaseOk && catOk;
+  }
+
+  function render() {
+    const grid = document.getElementById("grid");
+    const visible = TOOLS.filter(matches);
+    document.getElementById("result-count").innerHTML =
+      `Showing <span class="mono">${visible.length}</span> of <span class="mono">${TOOLS.length}</span> tools`;
+
+    if (visible.length === 0) {
