+      return;
+    }
+
+    grid.innerHTML = visible.map(tool => `
+      <article class="card">
+        <div class="card-head">
+          <h2><a href="${tool.url}" target="_blank" rel="noopener">${tool.name}</a></h2>
+          ${tool.vpn ? '<span class="vpn-badge">VPN required</span>' : ""}
+        </div>
