+        <p class="blurb">${tool.blurb}</p>
+        <div class="card-foot">
+          <span class="tag">${tool.category}</span>
+          ${tool.phases.map(p => `<span class="phase-tag" style="color:${PHASES[p].color};background:${PHASES[p].bg}"><span class="dot" style="width:.4rem;height:.4rem;border-radius:50%;background:${PHASES[p].color}"></span>${PHASES[p].label}</span>`).join("")}
+        </div>
+      </article>
+    `).join("");
+  }
+
+  document.getElementById("search").addEventListener("input", e => {
+    state.query = e.target.value;
+    render();
+  });
+
+  buildLegend();
+  buildPhaseChips();
+  buildCategoryChips();
+  render();
+</script>
