+"""Environment-driven configuration for RegIntel.
+
+Reads configuration from the process environment. (The application
+entrypoint is responsible for loading its environment file if desired;
+this module never loads any file itself.)
+
+Variables:
+- CONFIDENCE_THRESHOLD : float, default 0.70. Non-numeric values raise
+  a clear error instead of being silently coerced.
+- REGINTEL_DB          : SQLite path, default ./regintel.db.
+"""
+
+from __future__ import annotations
+
+from os import environ
+
+CONFIDENCE_THRESHOLD_VAR = "CONFIDENCE_THRESHOLD"
+REGINTEL_DB_VAR = "REGINTEL_DB"
+
+DEFAULT_CONFIDENCE_THRESHOLD = 0.70
+DEFAULT_DB_PATH = "./regintel.db"
+
+
+def get_confidence_threshold() -> float:
+    """Return the confidence threshold.
+
+    Returns 0.70 when CONFIDENCE_THRESHOLD is unset; returns its float
+    value when set. A non-numeric value raises ValueError.
+    """
+    raw = environ.get(CONFIDENCE_THRESHOLD_VAR)
+    if raw is None or raw.strip() == "":
+        return DEFAULT_CONFIDENCE_THRESHOLD
+    raw = raw.strip()
+    try:
+        return float(raw)
+    except ValueError:
+        raise ValueError(
+            f"{CONFIDENCE_THRESHOLD_VAR} must be a number, "
+            f"got {raw!r}"
+        ) from None
+
+
+def get_db_path() -> str:
+    """Return the SQLite database path (REGINTEL_DB, default
+    ./regintel.db)."""
+    raw = environ.get(REGINTEL_DB_VAR)
+    if raw is None or raw.strip() == "":
+        return DEFAULT_DB_PATH
+    return raw
