+"""Data model for RegIntel (Monitoring + Relevance slice).
+
+Field lists here mirror the "Data Model" section of manifest.md exactly.
+Any change to a field must be made in both places.
+"""
+
+from __future__ import annotations
+
+from dataclasses import dataclass, field
+from typing import List, Optional
+
+
+@dataclass
+class EventRecord:
+    """One per ingested regulatory update."""
+
+    # Stable id, derived from source + detected date + content hash
+    event_id: str
+    source_id: str                      # e.g. "RU-003"
+    source_name: str
+    source_type: str                    # bulletin, ordinance tracker, legal alert, aggregator, ...
+    source_reliability: str             # "verified" / "unverified"
+    jurisdiction_level: str             # federal / state / county / city
+    jurisdiction_name: str
+    detected_at: str
+    effective_date: Optional[str] = None
+    is_pending_legislation: bool = False
+    raw_text: str = ""                  # unaltered source text
+    content_hash: str = ""
+    injection_suspected: bool = False
+    created_at: str = ""
+
+
+@dataclass
+class ClassificationRecord:
+    """One per classification; re-classification appends, never overwrites."""
+
+    event_id: str
+    bucket: str                         # relevant / irrelevant / duplicate / needs-review
+    proposed_bucket: Optional[str] = None
+    confidence: float = 0.0
+    rationale: str = ""
+    topic_tags: List[str] = field(default_factory=list)
+    duplicate_of: Optional[str] = None  # canonical event_id when bucket == "duplicate"
+    model: str = ""
+    prompt_version: str = ""
+    prompt_tokens: int = 0
+    completion_tokens: int = 0
+    cost_usd: float = 0.0
+    raw_model_output: str = ""
+    classified_at: str = ""
+    classification_id: Optional[int] = None  # DB row id, assigned on insert
+
+
+@dataclass
+class ReviewRecord:
+    """One per human review action. Append-only (audit trail)."""
+
+    event_id: str
+    reviewer: str
+    action: str                         # "approve" / "override"
+    final_bucket: str = ""
+    reviewer_rationale: str = ""
+    reviewed_at: str = ""
+    review_id: Optional[int] = None     # DB row id, assigned on insert
