+"""SQLite persistence for RegIntel, using only the stdlib sqlite3 module.
+
+Tables:
+- events          -- ingested regulatory updates
+- classifications -- model classifications (APPEND-ONLY)
+- reviews         -- human review actions (APPEND-ONLY)
+
+There is deliberately no update or delete operation for classifications
+or reviews: re-classifications and new review decisions are new rows,
+preserving the full audit trail.
+"""
+
+from __future__ import annotations
+
+import json
+import sqlite3
+from typing import List, Optional
+
+from regintel.models import ClassificationRecord, EventRecord, ReviewRecord
+
+_SCHEMA = """
+CREATE TABLE IF NOT EXISTS events (
+    event_id                 TEXT PRIMARY KEY,
+    source_id                TEXT NOT NULL,
+    source_name              TEXT NOT NULL,
+    source_type              TEXT NOT NULL,
+    source_reliability       TEXT NOT NULL,
+    jurisdiction_level       TEXT NOT NULL,
+    jurisdiction_name        TEXT NOT NULL,
+    detected_at              TEXT NOT NULL,
+    effective_date           TEXT,
+    is_pending_legislation   INTEGER NOT NULL DEFAULT 0,
+    raw_text                 TEXT NOT NULL DEFAULT '',
+    content_hash             TEXT NOT NULL DEFAULT '',
+    injection_suspected      INTEGER NOT NULL DEFAULT 0,
+    created_at               TEXT NOT NULL DEFAULT ''
+);
+
+CREATE TABLE IF NOT EXISTS classifications (
+    classification_id    INTEGER PRIMARY KEY AUTOINCREMENT,
+    event_id             TEXT NOT NULL REFERENCES events(event_id),
+    bucket               TEXT NOT NULL,
+    proposed_bucket      TEXT,
+    confidence           REAL NOT NULL DEFAULT 0,
+    rationale            TEXT NOT NULL DEFAULT '',
+    topic_tags           TEXT NOT NULL DEFAULT '[]',   -- JSON array
+    duplicate_of         TEXT,
+    model                TEXT NOT NULL DEFAULT '',
+    prompt_version       TEXT NOT NULL DEFAULT '',
+    prompt_tokens        INTEGER NOT NULL DEFAULT 0,
+    completion_tokens    INTEGER NOT NULL DEFAULT 0,
+    cost_usd             REAL NOT NULL DEFAULT 0,
+    raw_model_output     TEXT NOT NULL DEFAULT '',
+    classified_at        TEXT NOT NULL DEFAULT ''
+);
+
+CREATE TABLE IF NOT EXISTS reviews (
+    review_id            INTEGER PRIMARY KEY AUTOINCREMENT,
+    event_id             TEXT NOT NULL REFERENCES events(event_id),
+    reviewer             TEXT NOT NULL,
+    action               TEXT NOT NULL,                -- approve / override
+    final_bucket         TEXT NOT NULL DEFAULT '',
+    reviewer_rationale   TEXT NOT NULL DEFAULT '',
+    reviewed_at          TEXT NOT NULL DEFAULT ''
+);
+
+CREATE INDEX IF NOT EXISTS idx_classifications_event
+    ON classifications(event_id);
+CREATE INDEX IF NOT EXISTS idx_reviews_event
+    ON reviews(event_id);
+"""
+
+
+def init_db(path: str) -> sqlite3.Connection:
+    """Open (creating if needed) the database at *path* and ensure the
+    schema exists.
+
+    Idempotent: calling this again against the same database file does
+    not raise and leaves prior rows intact (CREATE TABLE IF NOT EXISTS).
+    """
+    conn = sqlite3.connect(path)
+    conn.execute("PRAGMA foreign_keys = ON")
+    conn.executescript(_SCHEMA)
+    conn.commit()
+    return conn
+
+
+def _row_to_event(row: sqlite3.Row) -> EventRecord:
+    return EventRecord(
+        event_id=row["event_id"],
+        source_id=row["source_id"],
+        source_name=row["source_name"],
+        source_type=row["source_type"],
+        source_reliability=row["source_reliability"],
+        jurisdiction_level=row["jurisdiction_level"],
+        jurisdiction_name=row["jurisdiction_name"],
+        detected_at=row["detected_at"],
+        effective_date=row["effective_date"],
+        is_pending_legislation=bool(row["is_pending_legislation"]),
+        raw_text=row["raw_text"],
+        content_hash=row["content_hash"],
+        injection_suspected=bool(row["injection_suspected"]),
+        created_at=row["created_at"],
+    )
+
+
+def _row_to_classification(row: sqlite3.Row) -> ClassificationRecord:
+    try:
+        topic_tags = json.loads(row["topic_tags"])
+    except (TypeError, ValueError):
+        topic_tags = []
+    return ClassificationRecord(
+        classification_id=row["classification_id"],
+        event_id=row["event_id"],
+        bucket=row["bucket"],
+        proposed_bucket=row["proposed_bucket"],
+        confidence=row["confidence"],
+        rationale=row["rationale"],
+        topic_tags=topic_tags,
+        duplicate_of=row["duplicate_of"],
+        model=row["model"],
+        prompt_version=row["prompt_version"],
+        prompt_tokens=row["prompt_tokens"],
+        completion_tokens=row["completion_tokens"],
+        cost_usd=row["cost_usd"],
+        raw_model_output=row["raw_model_output"],
+        classified_at=row["classified_at"],
+    )
+
+
+def _row_to_review(row: sqlite3.Row) -> ReviewRecord:
+    return ReviewRecord(
+        review_id=row["review_id"],
+        event_id=row["event_id"],
+        reviewer=row["reviewer"],
+        action=row["action"],
+        final_bucket=row["final_bucket"],
+        reviewer_rationale=row["reviewer_rationale"],
+        reviewed_at=row["reviewed_at"],
+    )
+
+
+def insert_event(conn: sqlite3.Connection, event: EventRecord) -> None:
+    """Insert a new event row. Raises sqlite3.IntegrityError if an event
+    with the same event_id already exists."""
+    conn.execute(
+        """
+        INSERT INTO events (event_id, source_id, source_name, source_type,
+                            source_reliability, jurisdiction_level,
+                            jurisdiction_name, detected_at, effective_date,
+                            is_pending_legislation, raw_text, content_hash,
+                            injection_suspected, created_at)
+        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
+        """,
+        (
+            event.event_id,
+            event.source_id,
+            event.source_name,
+            event.source_type,
+            event.source_reliability,
+            event.jurisdiction_level,
+            event.jurisdiction_name,
+            event.detected_at,
+            event.effective_date,
+            int(event.is_pending_legislation),
+            event.raw_text,
+            event.content_hash,
+            int(event.injection_suspected),
+            event.created_at,
+        ),
+    )
+    conn.commit()
+
+
+def get_event(conn: sqlite3.Connection, event_id: str) -> Optional[EventRecord]:
+    """Return the event with *event_id*, or None if not found."""
+    conn.row_factory = sqlite3.Row
+    cur = conn.execute(
+        "SELECT * FROM events WHERE event_id = ?", (event_id,)
+    )
+    row = cur.fetchone()
+    if row is None:
+        return None
+    return _row_to_event(row)
+
+
+def list_events(conn: sqlite3.Connection) -> List[EventRecord]:
+    """Return all events, ordered by event_id."""
+    conn.row_factory = sqlite3.Row
+    cur = conn.execute("SELECT * FROM events ORDER BY event_id")
+    return [_row_to_event(row) for row in cur.fetchall()]
+
+
+def append_classification(
+    conn: sqlite3.Connection, record: ClassificationRecord
+) -> int:
+    """Append a classification row (append-only) and return its row id."""
+    cur = conn.execute(
+        """
+        INSERT INTO classifications (event_id, bucket, proposed_bucket,
+                                     confidence, rationale, topic_tags,
+                                     duplicate_of, model, prompt_version,
+                                     prompt_tokens, completion_tokens,
+                                     cost_usd, raw_model_output,
+                                     classified_at)
+        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
+        """,
+        (
+            record.event_id,
+            record.bucket,
+            record.proposed_bucket,
+            record.confidence,
+            record.rationale,
+            json.dumps(record.topic_tags),
+            record.duplicate_of,
+            record.model,
+            record.prompt_version,
+            record.prompt_tokens,
+            record.completion_tokens,
+            record.cost_usd,
+            record.raw_model_output,
+            record.classified_at,
+        ),
+    )
+    conn.commit()
+    return int(cur.lastrowid)
+
+
+def latest_classification(
+    conn: sqlite3.Connection, event_id: str
+) -> Optional[ClassificationRecord]:
+    """Return the most recent classification for *event_id*, or None."""
+    conn.row_factory = sqlite3.Row
+    cur = conn.execute(
+        """
+        SELECT * FROM classifications
+        WHERE event_id = ?
+        ORDER BY classification_id DESC
+        LIMIT 1
+        """,
+        (event_id,),
+    )
+    row = cur.fetchone()
+    if row is None:
+        return None
+    return _row_to_classification(row)
+
+
+def list_classifications(
+    conn: sqlite3.Connection, event_id: str
+) -> List[ClassificationRecord]:
+    """Return all classifications for *event_id*, oldest first."""
+    conn.row_factory = sqlite3.Row
+    cur = conn.execute(
+        """
+        SELECT * FROM classifications
+        WHERE event_id = ?
+        ORDER BY classification_id ASC
+        """,
+        (event_id,),
+    )
+    return [_row_to_classification(row) for row in cur.fetchall()]
+
+
+def append_review(conn: sqlite3.Connection, record: ReviewRecord) -> int:
+    """Append a review row (append-only) and return its row id."""
+    cur = conn.execute(
+        """
+        INSERT INTO reviews (event_id, reviewer, action, final_bucket,
+                             reviewer_rationale, reviewed_at)
+        VALUES (?, ?, ?, ?, ?, ?)
+        """,
+        (
+            record.event_id,
+            record.reviewer,
+            record.action,
+            record.final_bucket,
+            record.reviewer_rationale,
+            record.reviewed_at,
+        ),
+    )
+    conn.commit()
+    return int(cur.lastrowid)
+
+
+def list_reviews(conn: sqlite3.Connection, event_id: str) -> List[ReviewRecord]:
+    """Return all reviews for *event_id*, oldest first."""
+    conn.row_factory = sqlite3.Row
+    cur = conn.execute(
+        """
+        SELECT * FROM reviews
+        WHERE event_id = ?
+        ORDER BY review_id ASC
+        """,
+        (event_id,),
+    )
+    return [_row_to_review(row) for row in cur.fetchall()]
