+#!/usr/bin/env bash
+# RegIntel scaffold: create .venv and install requirements.txt into it.
+# Fails loudly (non-zero exit, pip output printed) if installation cannot
+# complete — never leaves a silent partial/broken .venv behind.
+set -euo pipefail
+
+cd "$(dirname "$0")"
+
+PYTHON="${PYTHON:-python3}"
+
+if [ ! -x ".venv/bin/python" ]; then
+    echo "==> Creating virtual environment at .venv"
+    "$PYTHON" -m venv .venv
+fi
+
+echo "==> Upgrading pip"
+if ! .venv/bin/python -m pip install --upgrade pip; then
+    echo "ERROR: pip upgrade failed; aborting scaffold." >&2
+    exit 1
+fi
+
+echo "==> Installing requirements.txt into .venv"
+if ! .venv/bin/python -m pip install -r requirements.txt; then
+    echo "ERROR: requirements installation failed; aborting scaffold." >&2
+    exit 1
+fi
+
+echo "==> Smoke test: importing regintel and dependencies"
+if ! .venv/bin/python -c 'import regintel.store; import fastapi, openai, dotenv, pytest, httpx'; then
+    echo "ERROR: smoke-test import failed; .venv may be broken." >&2
+    exit 1
+fi
+
+echo "==> Scaffold complete."

