+"""Runtime configuration for Regintel Studio.
+
+All values are read from environment variables at call time (not import
+time), so tests and the FastAPI app can override them with `monkeypatch`
+or process env without re-importing. No value is read from `.env`
+directly — the project relies on the shell/process environment.
+"""
+from __future__ import annotations
+
+import os
+from pathlib import Path
+
+DEFAULT_CONFIDENCE_THRESHOLD = 0.70
+DEFAULT_DB_PATH = "./regintel.db"
+
+
+def confidence_threshold() -> float:
+    """Return the classification confidence threshold.
+
+    Reads the `CONFIDENCE_THRESHOLD` env var; falls back to the manifest
+    default (0.70) when unset. A blank env var is treated as unset so an
+    empty `CONFIDENCE_THRESHOLD=` in the environment does not crash.
+    """
+    raw = os.environ.get("CONFIDENCE_THRESHOLD")
+    if raw is None or raw.strip() == "":
+        return DEFAULT_CONFIDENCE_THRESHOLD
+    return float(raw)
+
+
+def db_path() -> Path:
+    """Return the SQLite database path (env: REGINTEL_DB, default ./regintel.db)."""
+    raw = os.environ.get("REGINTEL_DB")
+    if raw is None or raw.strip() == "":
+        return Path(DEFAULT_DB_PATH)
+    return Path(raw)
