+"""Dataclasses for Regintel Studio — matches manifest.md 'Data Model'.
+
+Field names mirror the manifest one-for-one. `EventRecord` is a single
+ingested regulatory update; `ClassificationRecord` is one model pass
+(re-classification appends a new row, never overwrites); `ReviewRecord`
+is one human action (also append-only).
+"""
+from __future__ import annotations
+
+from dataclasses import dataclass, field
+from datetime import datetime
+from typing import Optional
+
+
+@dataclass
+class EventRecord:
+    """One ingested regulatory update."""
+
+    event_id: str
+    source_id: str
+    source_name: str
+    source_type: str
+    source_reliability: str
+    jurisdiction_level: str
+    jurisdiction_name: str
+    detected_at: datetime
+    effective_date: Optional[datetime]
+    is_pending_legislation: bool
+    raw_text: str
+    content_hash: str
+    injection_suspected: bool
+    created_at: datetime
+
+
+@dataclass
+class ClassificationRecord:
+    """One model classification pass — append-only."""
+
+    event_id: str
+    bucket: str
+    proposed_bucket: str
+    confidence: float
+    rationale: str
+    topic_tags: list[str] = field(default_factory=list)
