+++ b/regintel/store.py
@@ -0,0 +1,364 @@
+"""SQLite persistence layer (stdlib sqlite3 only).
+
+Tables:
+    events          — one row per ingested regulatory update (EventRecord)
+    classifications — append-only log of model classification passes
+                      (ClassificationRecord). Re-classification inserts a
+                      new row; existing rows are never updated or deleted.
+    reviews         — append-only log of human reviewer actions
+                      (ReviewRecord). Never updated or deleted.
+
+The store is deliberately small and explicit so the review queue and the
+audit trail survive process restarts and can be inspected with `sqlite3`
+on the command line.
+"""
+from __future__ import annotations
+
+import sqlite3
+from datetime import datetime
+from pathlib import Path
+from typing import Optional
+
+from .models import ClassificationRecord, EventRecord, ReviewRecord
+
+
+# ----- schema ----------------------------------------------------------------
+
+_SCHEMA = """
+CREATE TABLE IF NOT EXISTS events (
+    event_id              TEXT PRIMARY KEY,
+    source_id             TEXT NOT NULL,
+    source_name           TEXT NOT NULL,
+    source_type           TEXT NOT NULL,
+    source_reliability    TEXT NOT NULL,
+    jurisdiction_level    TEXT NOT NULL,
+    jurisdiction_name     TEXT NOT NULL,
+    detected_at           TEXT NOT NULL,
+    effective_date        TEXT,
+    is_pending_legislation INTEGER NOT NULL,
+    raw_text              TEXT NOT NULL,
+    content_hash          TEXT NOT NULL,
+    injection_suspected   INTEGER NOT NULL,
+    created_at            TEXT NOT NULL
+);
+
+CREATE TABLE IF NOT EXISTS classifications (
+    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
+    event_id            TEXT NOT NULL,
+    bucket              TEXT NOT NULL,
+    proposed_bucket     TEXT NOT NULL,
+    confidence          REAL NOT NULL,
+    rationale           TEXT NOT NULL,
+    topic_tags          TEXT NOT NULL,
+    duplicate_of        TEXT,
+    model               TEXT NOT NULL,
+    prompt_version      TEXT NOT NULL,
+    prompt_tokens       INTEGER NOT NULL,
+    completion_tokens   INTEGER NOT NULL,
+    cost_usd            REAL NOT NULL,
+    raw_model_output    TEXT NOT NULL,
+    classified_at       TEXT NOT NULL,
+    FOREIGN KEY (event_id) REFERENCES events(event_id)
+);
+
+CREATE TABLE IF NOT EXISTS reviews (
+    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
+    event_id            TEXT NOT NULL,
+    reviewer            TEXT NOT NULL,
+    action              TEXT NOT NULL,
+    final_bucket        TEXT NOT NULL,
+    reviewer_rationale  TEXT NOT NULL,
+    reviewed_at         TEXT NOT NULL,
+    FOREIGN KEY (event_id) REFERENCES events(event_id)
+);
+
+CREATE INDEX IF NOT EXISTS idx_classifications_event_id
+    ON classifications(event_id);
+CREATE INDEX IF NOT EXISTS idx_reviews_event_id
+    ON reviews(event_id);
+"""
+
+
+# ----- helpers ---------------------------------------------------------------
+
+
+def _iso(value: Optional[datetime]) -> Optional[str]:
+    """Serialise a datetime to ISO-8601 string; pass through None."""
+    if value is None:
+        return None
+    return value.isoformat()
+
+
+def _parse_iso(value: Optional[str]) -> Optional[datetime]:
+    """Inverse of `_iso`; tolerates NULL/None."""
+    if value is None or value == "":
+        return None
+    return datetime.fromisoformat(value)
+
+
+def connect(path: Path | str) -> sqlite3.Connection:
+    """Open a sqlite3 connection to `path` (does not initialise the schema).
+
+    The connection uses sqlite3.Row for column access. Callers are
+    responsible for closing the connection (use it as a context manager
+    or call `.close()` explicitly).
+    """
+    conn = sqlite3.connect(str(path))
+    conn.row_factory = sqlite3.Row
+    return conn
+
+
+# ----- lifecycle -------------------------------------------------------------
+
+
+def init_db(path: Path | str) -> Path:
+    """Create the schema at `path` if absent. Returns the resolved path.
+
+    Idempotent — safe to call at every process start.
+    """
+    db_path = Path(path).resolve()
+    db_path.parent.mkdir(parents=True, exist_ok=True)
+    conn = connect(db_path)
+    try:
+        conn.executescript(_SCHEMA)
+        conn.commit()
+    finally:
+        conn.close()
+    return db_path
+
+
+# ----- row mappers -----------------------------------------------------------
+
+
+def _row_to_event(row: sqlite3.Row) -> EventRecord:
+    return EventRecord(
+        event_id=row["event_id"],
+        source_id=row["source_id"],
+        source_name=row["source_name"],
+        source_type=row["source_type"],
+        source_reliability=row["source_reliability"],
+        jurisdiction_level=row["jurisdiction_level"],
+        jurisdiction_name=row["jurisdiction_name"],
+        detected_at=_parse_iso(row["detected_at"]),
+        effective_date=_parse_iso(row["effective_date"]),
+        is_pending_legislation=bool(row["is_pending_legislation"]),
+        raw_text=row["raw_text"],
+        content_hash=row["content_hash"],
+        injection_suspected=bool(row["injection_suspected"]),
+        created_at=_parse_iso(row["created_at"]),
+    )
+
+
+def _row_to_classification(row: sqlite3.Row) -> ClassificationRecord:
+    tags_raw = row["topic_tags"] or ""
+    tags = [t for t in tags_raw.split("\x1f") if t] if tags_raw else []
+    return ClassificationRecord(
+        event_id=row["event_id"],
+        bucket=row["bucket"],
+        proposed_bucket=row["proposed_bucket"],
+        confidence=float(row["confidence"]),
+        rationale=row["rationale"],
+        topic_tags=tags,
+        duplicate_of=row["duplicate_of"],
+        model=row["model"],
+        prompt_version=row["prompt_version"],
+        prompt_tokens=int(row["prompt_tokens"]),
+        completion_tokens=int(row["completion_tokens"]),
+        cost_usd=float(row["cost_usd"]),
+        raw_model_output=row["raw_model_output"],
+        classified_at=_parse_iso(row["classified_at"]),
+    )
+
+
+def _row_to_review(row: sqlite3.Row) -> ReviewRecord:
+    return ReviewRecord(
+        event_id=row["event_id"],
+        reviewer=row["reviewer"],
+        action=row["action"],
+        final_bucket=row["final_bucket"],
+        reviewer_rationale=row["reviewer_rationale"],
+        reviewed_at=_parse_iso(row["reviewed_at"]),
+    )
+
+
+# ----- events ----------------------------------------------------------------
+
+
+def insert_event(conn: sqlite3.Connection, event: EventRecord) -> None:
+    """Insert an EventRecord. No-op if `event_id` already exists.
+
+    The store treats `event_id` as the canonical primary key (see F1:
+    "Parsing is deterministic and idempotent"). Callers that want to
+    enforce idempotency explicitly can check `get_event()` first.
+    """
+    conn.execute(
+        """
+        INSERT OR IGNORE INTO events (
+            event_id, source_id, source_name, source_type, source_reliability,
+            jurisdiction_level, jurisdiction_name,
+            detected_at, effective_date, is_pending_legislation,
+            raw_text, content_hash, injection_suspected, created_at
+        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
+        """,
+        (
+            event.event_id,
+            event.source_id,
+            event.source_name,
+            event.source_type,
+            event.source_reliability,
+            event.jurisdiction_level,
+            event.jurisdiction_name,
+            _iso(event.detected_at),
+            _iso(event.effective_date),
+            1 if event.is_pending_legislation else 0,
+            event.raw_text,
+            event.content_hash,
+            1 if event.injection_suspected else 0,
+            _iso(event.created_at),
+        ),
+    )
+
+
+def get_event(conn: sqlite3.Connection, event_id: str) -> Optional[EventRecord]:
+    """Return the EventRecord for `event_id`, or None if not found."""
+    row = conn.execute(
+        "SELECT * FROM events WHERE event_id = ?", (event_id,)
+    ).fetchone()
+    return _row_to_event(row) if row is not None else None
+
+
+def list_events(conn: sqlite3.Connection) -> list[EventRecord]:
+    """Return all events ordered by `detected_at`, then `event_id`."""
+    rows = conn.execute(
+        "SELECT * FROM events ORDER BY detected_at, event_id"
+    ).fetchall()
+    return [_row_to_event(r) for r in rows]
+
+
+# ----- classifications (append-only) -----------------------------------------
+
+
+def append_classification(
+    conn: sqlite3.Connection, record: ClassificationRecord
+) -> int:
+    """Insert a new classification row. Never updates an existing row.
+
+    Returns the auto-increment id of the inserted row.
+    """
+    classified_at = record.classified_at or datetime.utcnow()
+    tags_blob = "\x1f".join(record.topic_tags)
+    cur = conn.execute(
+        """
+        INSERT INTO classifications (
+            event_id, bucket, proposed_bucket, confidence, rationale,
+            topic_tags, duplicate_of,
+            model, prompt_version, prompt_tokens, completion_tokens,
+            cost_usd, raw_model_output, classified_at
+        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
+        """,
+        (
+            record.event_id,
+            record.bucket,
+            record.proposed_bucket,
+            record.confidence,
+            record.rationale,
+            tags_blob,
+            record.duplicate_of,
+            record.model,
+            record.prompt_version,
+            record.prompt_tokens,
+            record.completion_tokens,
+            record.cost_usd,
+            record.raw_model_output,
+            _iso(classified_at),
+        ),
+    )
+    return int(cur.lastrowid)
+
+
+def latest_classification(
+    conn: sqlite3.Connection, event_id: str
+) -> Optional[ClassificationRecord]:
+    """Return the most recently inserted classification for `event_id`."""
+    row = conn.execute(
+        """
+        SELECT * FROM classifications
+        WHERE event_id = ?
+        ORDER BY id DESC
+        LIMIT 1
+        """,
+        (event_id,),
+    ).fetchone()
+    return _row_to_classification(row) if row is not None else None
+
+
+def list_classifications(
+    conn: sqlite3.Connection, event_id: str
+) -> list[ClassificationRecord]:
+    """Return all classifications for `event_id` in insertion order."""
+    rows = conn.execute(
+        """
+        SELECT * FROM classifications
+        WHERE event_id = ?
+        ORDER BY id ASC
+        """,
+        (event_id,),
+    ).fetchall()
+    return [_row_to_classification(r) for r in rows]
+
+
+# ----- reviews (append-only) -------------------------------------------------
+
+
+def append_review(conn: sqlite3.Connection, record: ReviewRecord) -> int:
+    """Insert a new review row. Never updates an existing row.
+
+    Returns the auto-increment id of the inserted row.
+    """
+    reviewed_at = record.reviewed_at or datetime.utcnow()
+    cur = conn.execute(
+        """
+        INSERT INTO reviews (
+            event_id, reviewer, action, final_bucket,
+            reviewer_rationale, reviewed_at
+        ) VALUES (?, ?, ?, ?, ?, ?)
+        """,
+        (
+            record.event_id,
+            record.reviewer,
+            record.action,
+            record.final_bucket,
+            record.reviewer_rationale,
+            _iso(reviewed_at),
+        ),
+    )
+    return int(cur.lastrowid)
+
+
+def list_reviews(
+    conn: sqlite3.Connection, event_id: str
+) -> list[ReviewRecord]:
+    """Return all reviews for `event_id` in insertion order."""
+    rows = conn.execute(
+        """
+        SELECT * FROM reviews
+        WHERE event_id = ?
+        ORDER BY id ASC
+        """,
+        (event_id,),
+    ).fetchall()
+    return [_row_to_review(r) for r in rows]
+
+
+__all__ = [
+    "init_db",
+    "connect",
+    "insert_event",
+    "get_event",
+    "list_events",
+    "append_classification",
+    "latest_classification",
+    "list_classifications",
+    "append_review",
+    "list_reviews",
+]
