+#!/usr/bin/env python3
+"""Regenerate the GitLab Wiki's home.md from docs/ai-tool-resource-guide.html.
+
+The HTML page embeds its tool data as a <script type="application/json"
+id="tool-data"> block -- that block is the single source of truth. This
+script extracts it and renders the same table onto the wiki's home page,
+since GitLab Pages isn't available on this instance to serve the HTML page
+directly.
+
+Usage:
+    python3 scripts/generate_wiki_page.py
+        Print the generated Markdown to stdout.
+
+    python3 scripts/generate_wiki_page.py --wiki-dir /path/to/wiki-clone
+        Write directly to <wiki-dir>/home.md. You still need to
+        `git add home.md && git commit && git push` inside that clone
+        (clone it once via `git clone <repo-url>.wiki.git`, then
+        `git checkout master` -- the wiki repo's HEAD symref is broken,
+        so a plain clone checks out nothing and a commit made without
+        checking out `master` first creates an unrelated root commit
+        instead of building on the real history).
+"""
+from __future__ import annotations
+
+import argparse
+import json
+import re
+import sys
+from pathlib import Path
+
+HTML_PATH = Path(__file__).resolve().parent.parent / "docs" / "ai-tool-resource-guide.html"
+DATA_BLOCK_RE = re.compile(
+    r'<script type="application/json" id="tool-data">(.*?)</script>', re.S
+)
+
+
+def load_data() -> dict:
+    html = HTML_PATH.read_text(encoding="utf-8")
+    match = DATA_BLOCK_RE.search(html)
+    if not match:
+        raise SystemExit(f"Couldn't find the tool-data <script> block in {HTML_PATH}")
+    return json.loads(match.group(1))
+
+
+def render(data: dict) -> str:
+    phases = data["phases"]
+    tools = data["tools"]
+    stage_legend = " · ".join(f"{i + 1} = {p['label'].split('· ')[-1]}" for i, p in enumerate(phases.values()))
+
+    lines = [
+        "# AI Tool Resource Guide",
+        "",
+        "EPAM AI tools and resources relevant to this workshop, tagged by which",
+        "challenge each one can help with. (Originally built as a searchable/",
+        "filterable HTML page — `docs/ai-tool-resource-guide.html` in the repo has",
+        "the live search/filter version with the same content; GitLab Pages isn't",
+        "enabled on this instance, so this Wiki page is the browsable copy.)",
+        "",
+        f"**Workshop stages:** {stage_legend}",
+        "",
+        "| Tool | Category | Stage(s) | VPN | What it does |",
+        "|---|---|---|---|---|",
+    ]
+
+    phase_keys = list(phases.keys())
+    for tool in tools:
+        stage_numbers = ", ".join(str(phase_keys.index(p) + 1) for p in tool["phases"])
+        vpn = "**Yes**" if tool["vpn"] else "No"
+        blurb = tool["blurb"].replace("|", "\\|")
+        lines.append(
+            f"| [{tool['name']}]({tool['url']}) | {tool['category']} | {stage_numbers} | {vpn} | {blurb} |"
+        )
+
+    lines += [
+        "",
+        "Use your browser's find-in-page (Ctrl/Cmd+F) to filter by keyword, category,",
+        "or stage number — this table doesn't have the live JS search/filter that",
+        "the HTML version has.",
+        "",
+    ]
+    return "\n".join(lines)
+
+
+def main() -> None:
+    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
+    parser.add_argument(
+        "--wiki-dir",
+        type=Path,
+        default=None,
+        help="Path to a local clone of the project's .wiki.git repo. If omitted, prints to stdout.",
+    )
+    args = parser.parse_args()
+
+    markdown = render(load_data())
+
+    if args.wiki_dir is None:
+        print(markdown)
+        return
+
+    out_path = args.wiki_dir / "home.md"
+    out_path.write_text(markdown, encoding="utf-8")
+    print(f"Wrote {out_path}. Now: cd {args.wiki_dir} && git add home.md && git commit -m 'Sync from docs/ai-tool-resource-guide.html' && git push", file=sys.stderr)
+
+
+if __name__ == "__main__":
+    main()
