@@ -0,0 +1,69 @@
+"""Verify DIAL connectivity end-to-end — not just that env vars are set.
+
+Run from the repo root, after filling in .env:
+
+    python3 scripts/verify_dial.py
+
+It makes one real chat completion call through the dial package and reports
+a specific, actionable diagnosis if it fails (missing config, VPN, bad key,
+bad deployment name) instead of a raw stack trace.
+"""
+import asyncio
+import os
+import sys
+from pathlib import Path
+
+import httpx
+import openai
+
+sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
+
+from dial import DEFAULT_MODEL, get_async_client, is_configured
+
+
+async def main() -> int:
+    if not is_configured():
+        print("FAIL: DIAL_API_ENDPOINT / DIAL_API_KEY not set.")
+        print("      Copy .env.example to .env and fill in your values. See SETUP.md.")
+        return 1
+
+    model = os.environ.get("DIAL_MODEL") or DEFAULT_MODEL
+    client = get_async_client(model)
+
+    try:
+        response = await client.chat.completions.create(
+            model=model,  # required by the OpenAI SDK's request schema, even
+                          # though DIAL routes by the deployment in base_url
+            messages=[{"role": "user", "content": "Reply with the single word: pong"}],
+            max_tokens=5,
+        )
+    except (httpx.ConnectError, httpx.ConnectTimeout, openai.APIConnectionError):
+        print("FAIL: could not reach the DIAL endpoint.")
+        print("      Are you on the EPAM VPN? DIAL is only reachable from it.")
+        print("      Also double-check DIAL_API_ENDPOINT in .env for typos.")
+        return 1
+    except openai.AuthenticationError:
+        print("FAIL: DIAL rejected the API key (401).")
+        print("      Check DIAL_API_KEY in .env — it may be wrong, expired, or revoked.")
+        return 1
+    except openai.NotFoundError:
+        print("FAIL: DIAL returned 404 — the deployment name is probably wrong.")
+        print("      List valid deployments and fix DIAL_MODEL in .env:")
+        print('      curl "$DIAL_API_ENDPOINT/openai/models" -H "api-key: $DIAL_API_KEY"')
+        return 1
+    except openai.APITimeoutError:
+        print("FAIL: request timed out.")
+        print("      Usually means you're not on the EPAM VPN.")
+        return 1
+    except Exception as exc:  # noqa: BLE001 — last resort, show what we got
+        print(f"FAIL: unexpected error calling DIAL: {exc!r}")
+        return 1
+
+    reply = (response.choices[0].message.content or "").strip()
+    print(f"OK: DIAL call succeeded. Model replied: {reply!r}")
+    print(f"    Usage: {response.usage}")
+    return 0
+
+
+if __name__ == "__main__":
+    sys.exit(asyncio.run(main()))

