@@ -0,0 +1,61 @@
+"""Shared DIAL API client factory — async, OpenAI-compatible.
+
+Configuration via env vars, loaded from .env:
+
+  DIAL_API_ENDPOINT  — DIAL host, no path (e.g. https://ai-proxy.lab.epam.com).
+                        The /openai/deployments/{model}/... path is appended
+                        by this module — don't include it yourself.
+  DIAL_API_KEY       — gateway API key (request via the EPAM DIAL service
+                        catalog item — see SETUP.md)
+  DIAL_MODEL         — deployment name, not the raw model name. List yours via:
+                        curl "$DIAL_API_ENDPOINT/openai/models" -H "api-key: $DIAL_API_KEY"
+  DIAL_BASE_URL      — optional. Full base URL for a non-DIAL OpenAI-compatible
+                        gateway (e.g. the CodeMie local proxy at
+                        http://127.0.0.1:4001/v1). When set, it replaces the
+                        DIAL deployment path; DIAL_API_KEY is still sent.
+
+Use this client for ALL LLM calls your solution makes at runtime (risk
+classification, draft response generation, etc). It is the only sanctioned
+path to a model — do not call a public LLM API directly. That is the
+"zero data leakage to public models" constraint from the client brief.
+"""
+import os
+from pathlib import Path
+from typing import Optional
+
+from dotenv import load_dotenv
+from openai import AsyncOpenAI
+
+load_dotenv(Path(__file__).resolve().parent.parent / ".env")
+
+DEFAULT_MODEL = "claude-haiku-4-5@20251001"
+
+
+def _dial_config() -> tuple[str, str]:
+    endpoint = os.environ.get("DIAL_API_ENDPOINT", "").strip()
+    key = os.environ.get("DIAL_API_KEY", "").strip()
+    return endpoint, key
+
+
+def is_configured() -> bool:
+    endpoint, key = _dial_config()
+    return bool(endpoint and key)
+
+
+def _base_url(endpoint: str, model: str) -> str:
+    """DIAL uses Azure-style routing: /openai/deployments/{model}/chat/completions."""
+    return f"{endpoint.rstrip('/')}/openai/deployments/{model}"
+
+
+def get_async_client(model: Optional[str] = None) -> AsyncOpenAI:
+    endpoint, key = _dial_config()
+    if not (endpoint and key):
+        raise RuntimeError(
+            "DIAL_API_ENDPOINT / DIAL_API_KEY not set — copy .env.example to "
+            ".env and fill in your values. See SETUP.md."
+        )
+    # os.environ.get(key, default) only falls back when the key is absent —
+    # a present-but-empty DIAL_MODEL= in .env would otherwise win as "".
+    model = model or os.environ.get("DIAL_MODEL") or DEFAULT_MODEL
+    base_url = os.environ.get("DIAL_BASE_URL", "").strip() or _base_url(endpoint, model)
+    return AsyncOpenAI(api_key=key, base_url=base_url, default_headers={"api-key": key})
