+"""Runtime configuration loaded from environment variables.
+
+Only environment variables are read here — never ``.env`` directly. The
+dial client (the only sanctioned env-loading surface per manifest.md)
+loads ``.env`` once at import time, so values set in ``.env`` are visible
+through ``os.environ`` to this module as well.
+
+Values:
+    CONFIDENCE_THRESHOLD  — float in [0.0, 1.0]. Default 0.70 (per
+                            manifest.md, "Confidence threshold ... env
+                            var, default 0.70"). An invalid / unset value
+                            falls back to the default.
+    REGINTEL_DB           — filesystem path to the SQLite database file.
+                            Default ./regintel.db (relative to the
+                            process's current working directory).
+"""
+from __future__ import annotations
+
+import os
+from typing import Union
+
+DEFAULT_CONFIDENCE_THRESHOLD: float = 0.70
+DEFAULT_DB_PATH: str = "./regintel.db"
+
+
+def confidence_threshold() -> float:
+    """Return the configured confidence threshold.
+
+    Reads ``CONFIDENCE_THRESHOLD`` from the environment. If it is unset,
+    blank, or not parseable as a float, returns the documented default
+    (0.70). The default matches the manifest's "Confidence threshold"
+    section and the project configuration key
+    ``confidenceThresholdDefault``.
+    """
+    raw = os.environ.get("CONFIDENCE_THRESHOLD")
+    if raw is None or not raw.strip():
+        return DEFAULT_CONFIDENCE_THRESHOLD
+    try:
+        value = float(raw)
+    except (TypeError, ValueError):
+        return DEFAULT_CONFIDENCE_THRESHOLD
+    return value
+
+
+def db_path() -> str:
+    """Return the path to the SQLite database file.
+
+    Reads ``REGINTEL_DB`` from the environment, defaulting to
+    ``./regintel.db``. The caller is responsible for ensuring the
+    parent directory exists if it is anything other than ".".
+    """
+    raw = os.environ.get("REGINTEL_DB")
+    if raw is None or not raw.strip():
+        return DEFAULT_DB_PATH
+    return raw
+
+
+__all__ = [
+    "DEFAULT_CONFIDENCE_THRESHOLD",
+    "DEFAULT_DB_PATH",
+    "confidence_threshold",
+    "db_path",
+]
