+"""Data model for RegIntel Studio — Monitoring + Relevance slice.
+
+Field names mirror those defined in `manifest.md` under "Data Model".
+
+Conventions:
+    - Dataclasses are frozen where they describe immutable, append-only
+      records (ClassificationRecord, ReviewRecord) so accidental mutation
+      is caught at runtime.
+    - EventRecord is mutable because it represents the canonical ingest
+      record and may carry derived flags (e.g. ``injection_suspected``)
+      that later ingest passes set after construction.
+    - Timestamps are ISO-8601 strings in UTC ("Z" or "+00:00" suffix),
+      not datetimes — the store stores them as TEXT per the SQLite
+      convention, and the LLM / API layers can compare and parse them
+      without tzinfo gymnastics.
+"""
+from __future__ import annotations
+
+from dataclasses import dataclass, field
+from typing import List, Optional
+
+
+@dataclass
+class EventRecord:
+    """One ingested regulatory update.
+
+    ``event_id`` is the stable identity derived from source + detected
+    date + content hash (see F1 in the manifest). Re-ingesting the same
+    source material must produce the same ``event_id``.
+    """
+
+    event_id: str
+    source_id: str
+    source_name: str
+    source_type: str
+    source_reliability: str  # "verified" | "unverified"
+    jurisdiction_level: str  # federal | state | county | city
+    jurisdiction_name: str
+    detected_at: str  # ISO-8601 UTC
+    effective_date: Optional[str]  # ISO-8601 UTC, nullable
+    is_pending_legislation: bool
+    raw_text: str
+    content_hash: str
+    injection_suspected: bool = False
+    created_at: str = ""  # set by store on insert if blank
+
+
+@dataclass(frozen=True)
+class ClassificationRecord:
+    """One classification outcome for an event.
+
+    Re-classification appends a new record; the original is never
+    overwritten (F4, append-only guarantee).
+    """
+
+    event_id: str
+    bucket: str  # relevant | irrelevant | duplicate | needs-review
+    proposed_bucket: str
+    confidence: float
+    rationale: str
+    topic_tags: List[str] = field(default_factory=list)
+    duplicate_of: Optional[str] = None
+    model: str = ""
+    prompt_version: str = ""
+    prompt_tokens: int = 0
+    completion_tokens: int = 0
+    cost_usd: float = 0.0
+    raw_model_output: str = ""
+    classified_at: str = ""
+
+
+@dataclass(frozen=True)
+class ReviewRecord:
+    """One human reviewer action against an event.
+
+    A reviewer may act multiple times on the same event; every action
+    appends a row. The original classification is never modified (F6).
+    """
+
+    event_id: str
+    reviewer: str
+    action: str  # approve | override
+    final_bucket: str  # relevant | irrelevant | duplicate | needs-review
+    reviewer_rationale: str
+    reviewed_at: str = ""
