+"""SQLite-backed store for events, classifications and reviews.
+
+Uses the standard library's ``sqlite3`` module — no external DB driver.
+
+Tables:
+    events          — one row per ingested EventRecord.
+    classifications — append-only; one row per ClassificationRecord. Rows
+                      are never UPDATEd or DELETEd.
+    reviews         — append-only; one row per ReviewRecord. Rows are
+                      never UPDATEd or DELETEd.
+
+Append-only is enforced by *not exposing* any update / delete helpers —
+there is no public function in this module that mutates a classification
+or review row. The store API is intentionally narrow: insert + read.
+
+All timestamps are stored as ISO-8601 TEXT. ``rowid`` columns are not
+exposed; callers identify rows by ``event_id`` (plus, for collections,
+the natural insertion order).
+"""
+from __future__ import annotations
+
+import sqlite3
+from contextlib import contextmanager
+from pathlib import Path
+from typing import Iterable, Iterator, List, Sequence
+
+from .models import ClassificationRecord, EventRecord, ReviewRecord
+
+# ---------------------------------------------------------------------------
+# Schema
+# ---------------------------------------------------------------------------
+
+_SCHEMA_SQL = """
+CREATE TABLE IF NOT EXISTS events (
+    event_id                TEXT PRIMARY KEY,
+    source_id               TEXT NOT NULL,
+    source_name             TEXT NOT NULL,
+    source_type             TEXT NOT NULL,
+    source_reliability      TEXT NOT NULL,
+    jurisdiction_level      TEXT NOT NULL,
+    jurisdiction_name       TEXT NOT NULL,
+    detected_at             TEXT NOT NULL,
+    effective_date          TEXT,
+    is_pending_legislation  INTEGER NOT NULL,
+    raw_text                TEXT NOT NULL,
+    content_hash            TEXT NOT NULL,
+    injection_suspected     INTEGER NOT NULL DEFAULT 0,
+    created_at              TEXT NOT NULL
+);
+
+CREATE TABLE IF NOT EXISTS classifications (
+    classification_id   INTEGER PRIMARY KEY AUTOINCREMENT,
+    event_id            TEXT NOT NULL,
+    bucket              TEXT NOT NULL,
+    proposed_bucket     TEXT NOT NULL,
+    confidence          REAL NOT NULL,
+    rationale           TEXT NOT NULL,
+    topic_tags          TEXT NOT NULL,         -- JSON-encoded list
+    duplicate_of        TEXT,
+    model               TEXT NOT NULL,
+    prompt_version      TEXT NOT NULL,
+    prompt_tokens       INTEGER NOT NULL,
+    completion_tokens   INTEGER NOT NULL,
+    cost_usd            REAL NOT NULL,
+    raw_model_output    TEXT NOT NULL,
+    classified_at       TEXT NOT NULL,
+    FOREIGN KEY (event_id) REFERENCES events(event_id)
+);
+
+CREATE INDEX IF NOT EXISTS idx_classifications_event_id
+    ON classifications(event_id);
+
+CREATE TABLE IF NOT EXISTS reviews (
+    review_id           INTEGER PRIMARY KEY AUTOINCREMENT,
+    event_id            TEXT NOT NULL,
+    reviewer            TEXT NOT NULL,
+    action              TEXT NOT NULL,         -- approve | override
+    final_bucket        TEXT NOT NULL,
+    reviewer_rationale  TEXT NOT NULL,
+    reviewed_at         TEXT NOT NULL,
+    FOREIGN KEY (event_id) REFERENCES events(event_id)
+);
+
+CREATE INDEX IF NOT EXISTS idx_reviews_event_id
+    ON reviews(event_id);
+"""
+
+_INSERT_EVENT_SQL = """
+INSERT OR REPLACE INTO events (
+    event_id, source_id, source_name, source_type, source_reliability,
+    jurisdiction_level, jurisdiction_name, detected_at, effective_date,
+    is_pending_legislation, raw_text, content_hash,
+    injection_suspected, created_at
+) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?);
+"""
+
+_GET_EVENT_SQL = "SELECT * FROM events WHERE event_id = ?;"
+
+_LIST_EVENTS_SQL = "SELECT * FROM events ORDER BY rowid;"
+
+_APPEND_CLASSIFICATION_SQL = """
+INSERT INTO classifications (
+    event_id, bucket, proposed_bucket, confidence, rationale, topic_tags,
+    duplicate_of, model, prompt_version, prompt_tokens, completion_tokens,
+    cost_usd, raw_model_output, classified_at
+) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?);
+"""
+
+_LATEST_CLASSIFICATION_SQL = """
+SELECT * FROM classifications
+WHERE event_id = ?
+ORDER BY classification_id DESC
+LIMIT 1;
+"""
+
+_LIST_CLASSIFICATIONS_SQL = """
+SELECT * FROM classifications
+WHERE event_id = ?
+ORDER BY classification_id ASC;
+"""
+
+_APPEND_REVIEW_SQL = """
+INSERT INTO reviews (
+    event_id, reviewer, action, final_bucket, reviewer_rationale, reviewed_at
+) VALUES (?, ?, ?, ?, ?, ?);
+"""
+
+_LIST_REVIEWS_SQL = """
+SELECT * FROM reviews
+WHERE event_id = ?
+ORDER BY review_id ASC;
+"""
+
+_EVENT_COLUMNS: Sequence[str] = (
+    "event_id", "source_id", "source_name", "source_type", "source_reliability",
+    "jurisdiction_level", "jurisdiction_name", "detected_at", "effective_date",
+    "is_pending_legislation", "raw_text", "content_hash",
+    "injection_suspected", "created_at",
+)
+
+_CLASSIFICATION_COLUMNS: Sequence[str] = (
+    "classification_id", "event_id", "bucket", "proposed_bucket", "confidence",
+    "rationale", "topic_tags", "duplicate_of", "model", "prompt_version",
+    "prompt_tokens", "completion_tokens", "cost_usd", "raw_model_output",
+    "classified_at",
+)
+
+_REVIEW_COLUMNS: Sequence[str] = (
+    "review_id", "event_id", "reviewer", "action", "final_bucket",
+    "reviewer_rationale", "reviewed_at",
+)
+
+
+# ---------------------------------------------------------------------------
+# Helpers
+# ---------------------------------------------------------------------------
+
+def _row_to_event(row: sqlite3.Row) -> EventRecord:
+    d = dict(row)
+    d["is_pending_legislation"] = bool(d["is_pending_legislation"])
+    d["injection_suspected"] = bool(d["injection_suspected"])
+    return EventRecord(
+        event_id=d["event_id"],
+        source_id=d["source_id"],
+        source_name=d["source_name"],
+        source_type=d["source_type"],
+        source_reliability=d["source_reliability"],
+        jurisdiction_level=d["jurisdiction_level"],
+        jurisdiction_name=d["jurisdiction_name"],
+        detected_at=d["detected_at"],
+        effective_date=d["effective_date"],
+        is_pending_legislation=d["is_pending_legislation"],
+        raw_text=d["raw_text"],
+        content_hash=d["content_hash"],
+        injection_suspected=d["injection_suspected"],
+        created_at=d["created_at"],
+    )
+
+
+def _row_to_classification(row: sqlite3.Row) -> ClassificationRecord:
+    import json
+    d = dict(row)
+    tags_raw = d.pop("topic_tags") or "[]"
+    try:
+        tags = json.loads(tags_raw)
+        if not isinstance(tags, list):
+            tags = []
+    except (TypeError, ValueError):
+        tags = []
+    d.pop("classification_id", None)
+    d["topic_tags"] = tags
+    return ClassificationRecord(**d)
+
+
+def _row_to_review(row: sqlite3.Row) -> ReviewRecord:
+    d = dict(row)
+    d.pop("review_id", None)
+    return ReviewRecord(**d)
+
+
+@contextmanager
+def _connect(path: str) -> Iterator[sqlite3.Connection]:
+    """Open a connection, set row factory, and yield it.
+
+    The caller is responsible for committing / rolling back; the
+    context manager only closes the connection.
+    """
+    # ``check_same_thread=False`` keeps tests simple; the rest of this
+    # module is single-connection-per-call.
+    conn = sqlite3.connect(path, check_same_thread=False)
+    try:
+        conn.row_factory = sqlite3.Row
+        conn.execute("PRAGMA foreign_keys = ON;")
+        yield conn
+    finally:
+        conn.close()
+
+
+# ---------------------------------------------------------------------------
+# Public API
+# ---------------------------------------------------------------------------
+
+def init_db(path: str) -> None:
+    """Create tables and indexes at ``path`` if they don't already exist.
+
+    Idempotent: safe to call multiple times against the same database.
+    The parent directory of ``path`` is created if it does not exist so
+    a freshly-checked-out repo works out of the box.
+    """
+    parent = Path(path).expanduser().resolve().parent
+    parent.mkdir(parents=True, exist_ok=True)
+    with _connect(path) as conn:
+        conn.executescript(_SCHEMA_SQL)
+        conn.commit()
+
+
+def insert_event(conn: sqlite3.Connection, event: EventRecord) -> None:
+    """Insert or replace an event row.
+
+    Uses ``INSERT OR REPLACE`` so re-ingest of the same fixture is
+    idempotent (the manifest's F1 requirement: same ``event_id`` ⇒ no
+    duplicate row). ``classification_id`` and ``review_id`` FKs are
+    preserved because ``event_id`` is unchanged across re-ingest.
+    """
+    conn.execute(
+        _INSERT_EVENT_SQL,
+        (
+            event.event_id,
+            event.source_id,
+            event.source_name,
+            event.source_type,
+            event.source_reliability,
+            event.jurisdiction_level,
+            event.jurisdiction_name,
+            event.detected_at,
+            event.effective_date,
+            1 if event.is_pending_legislation else 0,
+            event.raw_text,
+            event.content_hash,
+            1 if event.injection_suspected else 0,
+            event.created_at,
+        ),
+    )
+
+
+def get_event(conn: sqlite3.Connection, event_id: str) -> EventRecord | None:
+    """Return one event by id, or ``None`` if not present."""
+    row = conn.execute(_GET_EVENT_SQL, (event_id,)).fetchone()
+    return _row_to_event(row) if row is not None else None
+
+
+def list_events(conn: sqlite3.Connection) -> List[EventRecord]:
+    """Return every event in insertion order."""
+    rows = conn.execute(_LIST_EVENTS_SQL).fetchall()
+    return [_row_to_event(r) for r in rows]
+
+
+def append_classification(
+    conn: sqlite3.Connection, record: ClassificationRecord
+) -> None:
+    """Append a classification row.
+
+    Append-only: never UPDATE or DELETE. Each call inserts a new row,
+    preserving every prior classification for audit / re-classification.
+    """
+    import json
+    conn.execute(
+        _APPEND_CLASSIFICATION_SQL,
+        (
+            record.event_id,
+            record.bucket,
+            record.proposed_bucket,
+            float(record.confidence),
+            record.rationale,
+            json.dumps(list(record.topic_tags)),
+            record.duplicate_of,
+            record.model,
+            record.prompt_version,
+            int(record.prompt_tokens),
+            int(record.completion_tokens),
+            float(record.cost_usd),
+            record.raw_model_output,
+            record.classified_at,
+        ),
+    )
+
+
+def latest_classification(
+    conn: sqlite3.Connection, event_id: str
+) -> ClassificationRecord | None:
+    """Return the most recent classification for an event, or ``None``."""
+    row = conn.execute(
+        _LATEST_CLASSIFICATION_SQL, (event_id,)
+    ).fetchone()
+    return _row_to_classification(row) if row is not None else None
+
+
+def list_classifications(
+    conn: sqlite3.Connection, event_id: str
+) -> List[ClassificationRecord]:
+    """Return every classification for an event, oldest first."""
+    rows = conn.execute(
+        _LIST_CLASSIFICATIONS_SQL, (event_id,)
+    ).fetchall()
+    return [_row_to_classification(r) for r in rows]
+
+
+def append_review(conn: sqlite3.Connection, record: ReviewRecord) -> None:
+    """Append a review row.
+
+    Append-only: never UPDATE or DELETE. Multiple reviewer actions on
+    the same event each create a new row.
+    """
+    conn.execute(
+        _APPEND_REVIEW_SQL,
+        (
+            record.event_id,
+            record.reviewer,
+            record.action,
+            record.final_bucket,
+            record.reviewer_rationale,
+            record.reviewed_at,
+        ),
+    )
+
+
+def list_reviews(
+    conn: sqlite3.Connection, event_id: str
+) -> List[ReviewRecord]:
+    """Return every review action for an event, oldest first."""
+    rows = conn.execute(_LIST_REVIEWS_SQL, (event_id,)).fetchall()
+    return [_row_to_review(r) for r in rows]
+
+
+def open_connection(path: str) -> sqlite3.Connection:
+    """Open a configured connection for ad-hoc callers (API layer).
+
+    Convenience wrapper so callers don't reach into ``_connect``; the
+    returned connection must still be closed by the caller.
+    """
+    parent = Path(path).expanduser().resolve().parent
+    parent.mkdir(parents=True, exist_ok=True)
+    conn = sqlite3.connect(path, check_same_thread=False)
+    conn.row_factory = sqlite3.Row
+    conn.execute("PRAGMA foreign_keys = ON;")
+    return conn
+
+
+__all__ = [
+    "init_db",
+    "insert_event",
+    "get_event",
+    "list_events",
+    "append_classification",
+    "latest_classification",
+    "list_classifications",
+    "append_review",
+    "list_reviews",
+    "open_connection",
+]
