+  }
+
+  function renderRationale(text) {
+    var safe = escapeHtml(text || "");
+    if (!safe) return "";
+    var truncated = safe.length > 140 ? safe.slice(0, 140) + "…" : safe;
+    var display = truncated;
+    var moreBtn = "";
+    if (safe.length > 140) {
+      moreBtn = '<button type="button" class="rationale-toggle" data-toggle="rationale">Show more</button>';
