+    return '<span class="rationale-text" data-expanded="false">' + display + '</span>' + moreBtn;
+  }
+
+  function toggleRationale(td) {
+    var textSpan = td.querySelector(".rationale-text");
+    var toggleBtn = td.querySelector('[data-toggle="rationale"]');
+    if (!textSpan || !toggleBtn) return;
+    var expanded = textSpan.getAttribute("data-expanded") === "true";
+    var fullText = td.getAttribute("data-fulltext") || "";
+    if (expanded) {
+      textSpan.textContent = fullText.length > 140 ? fullText.slice(0, 140) + "…" : fullText;
+      textSpan.setAttribute("data-expanded", "false");
+      toggleBtn.textContent = "Show more";
+    } else {
+      textSpan.textContent = fullText;
+      textSpan.setAttribute("data-expanded", "true");
+      toggleBtn.textContent = "Show less";
+    }
+  }
+
+  function renderRow(row) {
+    var tr = document.createElement("tr");
+    tr.setAttribute("data-event-id", row.event_id);
+    tr.setAttribute("data-bucket", row.bucket || "");
+    tr.setAttribute("data-status", row.review_status || "");
+
+    var bc = bucketClass(row.bucket);
+
+    tr.innerHTML =
+      '<td>' + escapeHtml(row.source_id) + '</td>' +
+      '<td>' + escapeHtml(row.jurisdiction_name) + '</td>' +
+      '<td>' + escapeHtml(row.detected_at) + '</td>' +
+      '<td><span class="bucket-cell ' + bc + '">' + escapeHtml(row.bucket || "—") + '</span></td>' +
+      '<td>' + formatConfidence(row.confidence) + '</td>' +
+      '<td>' + (row.injection_suspected ? '<span class="flag-yes">YES</span>' : '<span class="flag-no">no</span>') + '</td>' +
+      '<td class="rationale-cell" data-fulltext="' + escapeHtml(row.rationale || "") + '">' + renderRationale(row.rationale) + '</td>' +
+      '<td><span class="status-' + escapeHtml(row.review_status || "pending") + '">' + escapeHtml(row.review_status || "pending") + '</span></td>' +
+      '<td class="actions"></td>';
+
+    var actionsTd = tr.querySelector(".actions");
+    actionsTd.appendChild(makeApproveButton(row.event_id));
+    actionsTd.appendChild(makeOverrideButton(row.event_id, tr));
+
+    var rationaleTd = tr.querySelector(".rationale-cell");
+    var toggle = rationaleTd.querySelector('[data-toggle="rationale"]');
+    if (toggle) {
+      toggle.addEventListener("click", function () { toggleRationale(rationaleTd); });
+    }
+
+    return tr;
+  }
+
+  function makeApproveButton(eventId) {
+    var btn = document.createElement("button");
+    btn.type = "button";
+    btn.className = "btn-approve";
+    btn.textContent = "Approve";
+    btn.addEventListener("click", function () { submitReview(eventId, "approve", null); });
+    return btn;
+  }
+
+  function makeOverrideButton(eventId, tr) {
+    var btn = document.createElement("button");
+    btn.type = "button";
+    btn.className = "btn-override";
+    btn.textContent = "Override";
+    btn.addEventListener("click", function () {
+      var existing = tr.querySelector(".override-form");
+      if (existing) {
+        existing.remove();
+        return;
+      }
+      var form = buildOverrideForm(eventId, tr);
+      tr.querySelector(".actions").appendChild(form);
+      var sel = form.querySelector("select");
+      if (sel) sel.focus();
+    });
+    return btn;
+  }
+
+  function buildOverrideForm(eventId, tr) {
+    var form = document.createElement("form");
+    form.className = "override-form";
+    form.innerHTML =
+      '<label>Final bucket<select name="final_bucket" required>' +
+        BUCKETS.map(function (b) { return '<option value="' + b + '">' + b + '</option>'; }).join("") +
+      '</select></label>' +
+      '<label>Reviewer<input type="text" name="reviewer" required autocomplete="off"></label>' +
+      '<label>Rationale<input type="text" name="reviewer_rationale" required autocomplete="off"></label>' +
+      '<div class="form-buttons">' +
+        '<button type="submit" class="btn-submit">Submit override</button>' +
+        '<button type="button" class="btn-cancel" data-cancel>Cancel</button>' +
+      '</div>';
+    form.addEventListener("submit", function (ev) {
+      ev.preventDefault();
+      var fd = new FormData(form);
+      var payload = {
+        action: "override",
+        final_bucket: fd.get("final_bucket"),
+        reviewer: (fd.get("reviewer") || "").toString().trim(),
+        reviewer_rationale: (fd.get("reviewer_rationale") || "").toString().trim()
+      };
+      if (!payload.final_bucket || !payload.reviewer || !payload.reviewer_rationale) {
+        showError("Bucket, reviewer, and rationale are all required for override.");
+        return;
+      }
+      form.querySelector(".btn-submit").disabled = true;
+      submitReview(eventId, "override", payload, form);
+    });
+    form.querySelector('[data-cancel]').addEventListener("click", function () {
+      form.remove();
+    });
+    return form;
+  }
+
+  function renderQueue() {
+    queueBody.innerHTML = "";
+    var visible = state.rows.filter(function (row) {
+      if (!state.filter) return true;
+      return row.bucket === state.filter;
+    });
+    if (visible.length === 0) {
+      var tr = document.createElement("tr");
+      tr.innerHTML = '<td colspan="9" class="empty-state">No events match the current filter.</td>';
+      queueBody.appendChild(tr);
+      return;
+    }
+    visible.forEach(function (row) {
+      queueBody.appendChild(renderRow(row));
+    });
+  }
+
+  function refreshRow(eventId) {
+    return fetch("/events/" + encodeURIComponent(eventId), { headers: { "Accept": "application/json" } })
+      .then(function (resp) {
+        if (!resp.ok) throw new Error("Failed to load event " + eventId + " (" + resp.status + ")");
+        return resp.json();
+      })
+      .then(function (detail) {
+        var reviews = (detail && detail.reviews) || [];
+        var classifications = (detail && detail.classifications) || [];
+        var latest = classifications[classifications.length - 1] || null;
+        var event = (detail && detail.event) || null;
+        var idx = state.rows.findIndex(function (r) { return r.event_id === eventId; });
+        if (idx === -1) {
+          if (event) {
+            state.rows.push(buildRowFromDetail(event, latest, reviews));
+          }
+        } else {
+          state.rows[idx] = buildRowFromDetail(event, latest, reviews) || state.rows[idx];
+        }
+        renderQueue();
+      });
+  }
+
+  function buildRowFromDetail(event, latest, reviews) {
+    if (!event) return null;
+    var latest_review = reviews && reviews.length ? reviews[reviews.length - 1] : null;
+    var final_bucket = latest_review ? latest_review.final_bucket : null;
+    var review_status = "pending";
+    if (latest_review) {
+      review_status = latest_review.action === "override" ? "overridden" : "approved";
+    }
+    var injection = !!event.injection_suspected;
+    var bucket = latest ? latest.bucket : null;
+    var rationale = latest ? latest.rationale : null;
+    var confidence = latest ? latest.confidence : null;
+    return {
+      event_id: event.event_id,
+      source_id: event.source_id,
+      source_name: event.source_name,
+      jurisdiction_name: event.jurisdiction_name,
+      detected_at: event.detected_at,
+      bucket: bucket,
+      proposed_bucket: latest ? latest.proposed_bucket : null,
+      confidence: confidence,
+      rationale: rationale,
+      injection_suspected: injection,
+      review_status: review_status,
+      final_bucket: final_bucket
+    };
+  }
+
+  function submitReview(eventId, action, payload, formEl) {
+    clearError();
+    var body = payload || {
+      action: "approve",
+      final_bucket: "relevant",
+      reviewer: "auto-approve",
+      reviewer_rationale: "Approved without override"
+    };
+    return fetch("/events/" + encodeURIComponent(eventId) + "/review", {
+      method: "POST",
+      headers: {
+        "Content-Type": "application/json",
+        "Accept": "application/json"
+      },
+      body: JSON.stringify(body)
+    }).then(function (resp) {
+      if (!resp.ok) {
+        return resp.text().then(function (txt) {
+          throw new Error("Review rejected (" + resp.status + "): " + txt);
+        });
+      }
+      return resp.json();
+    }).then(function () {
+      if (formEl) formEl.remove();
+      return refreshRow(eventId);
+    }).then(function () {
+      loadMetrics();
+    }).catch(function (err) {
+      showError((err && err.message) || "Review submission failed");
+      if (formEl) {
+        var btn = formEl.querySelector(".btn-submit");
+        if (btn) btn.disabled = false;
+      }
+    });
+  }
+
+  function loadQueue() {
+    clearError();
+    return fetch("/queue", { headers: { "Accept": "application/json" } })
+      .then(function (resp) {
+        if (!resp.ok) throw new Error("Failed to load queue (" + resp.status + ")");
+        return resp.json();
+      })
+      .then(function (data) {
+        state.rows = Array.isArray(data) ? data : [];
+        renderQueue();
+      })
+      .catch(function (err) {
+        queueBody.innerHTML = "";
+        showError((err && err.message) || "Could not load the review queue.");
+      });
+  }
+
+  function loadMetrics() {
+    return fetch("/metrics", { headers: { "Accept": "application/json" } })
+      .then(function (resp) {
+        if (!resp.ok) throw new Error("Failed to load metrics (" + resp.status + ")");
+        return resp.json();
+      })
+      .then(function (m) {
+        var counts = m.counts || m.buckets || {};
+        document.getElementById("metric-relevant").textContent      = counts["relevant"] || 0;
+        document.getElementById("metric-irrelevant").textContent    = counts["irrelevant"] || 0;
+        document.getElementById("metric-duplicate").textContent     = counts["duplicate"] || 0;
+        document.getElementById("metric-needs-review").textContent  = counts["needs-review"] || 0;
+        document.getElementById("metric-events").textContent        = (m.events !== undefined ? m.events : "-");
+        document.getElementById("metric-cost-per-event").textContent = formatNumber(m.cost_per_event_usd);
+        document.getElementById("metric-total-cost").textContent    = formatNumber(m.total_cost_usd);
+      })
+      .catch(function (err) {
+        showError((err && err.message) || "Could not load metrics.");
+      });
+  }
+
+  function onFilterChange() {
+    state.filter = filterSelect.value || "";
+    renderQueue();
+  }
+
+  filterSelect.addEventListener("change", onFilterChange);
+  refreshBtn.addEventListener("click", function () {
+    loadQueue();
+    loadMetrics();
+  });
+
+  document.addEventListener("DOMContentLoaded", function () {
+    loadQueue();
+    loadMetrics();
+  });
+
+  // Start load immediately in case the script runs after DOMContentLoaded already fired.
+  if (document.readyState === "interactive" || document.readyState === "complete") {
+    loadQueue();
+    loadMetrics();
+  }
+})();
+</script>
+</body>
+</html>

