+"""Configuration loaded from environment variables.
+
+Only stdlib (``os``) is used. ``regintel/`` code never reads ``.env`` — the
+copied ``dial/client.py`` is the only place that loads it.
+"""
+
+from __future__ import annotations
+
+import os
+from typing import Optional
+
+
+def confidence_threshold() -> float:
+    """Return the classification confidence threshold.
+
+    Reads the ``CONFIDENCE_THRESHOLD`` environment variable. Defaults to
+    ``0.70`` when unset. If set but non-numeric, raises ``ValueError``
+    naming the variable and the offending value (no silent fallback).
+    """
+    raw = os.environ.get("CONFIDENCE_THRESHOLD")
+    if raw is None:
+        return 0.70
+    try:
+        return float(raw)
+    except ValueError as exc:
+        raise ValueError(
+            f"CONFIDENCE_THRESHOLD is not a valid number: {raw!r}"
+        ) from exc
+
+
+def db_path(default: Optional[str] = None) -> str:
+    """Return the SQLite database file path.
+
+    Reads the ``REGINTEL_DB`` environment variable. Defaults to
+    ``./regintel.db`` (or the ``default`` argument if supplied) when unset.
+    """
+    return os.environ.get("REGINTEL_DB") or default or "./regintel.db"
