+"""Data model dataclasses for RegIntel Studio.
+
+Mirrors the "Data Model" section of manifest.md. These are plain dataclasses
+with no behaviour beyond construction; persistence is handled by
+``regintel.store``.
+"""
+
+from __future__ import annotations
+
+from dataclasses import dataclass, field
+from datetime import datetime
+from typing import List, Optional
+
+
+@dataclass
+class EventRecord:
+    """One ingested regulatory update.
+
+    Field set matches manifest.md 'Data Model' -> 'Event record'.
+    """
+
+    event_id: str
+    source_id: str
+    source_name: str
+    source_type: str
+    source_reliability: str
+    jurisdiction_level: str
+    jurisdiction_name: str
+    detected_at: str
+    effective_date: Optional[str]
+    is_pending_legislation: bool
+    raw_text: str
+    content_hash: str
+    injection_suspected: bool = False
+    created_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())
+
+
+@dataclass
+class ClassificationRecord:
+    """One classifier decision for an event.
+
+    Re-classification APPENDS a new row; rows are never updated.
+    Field set matches manifest.md 'Data Model' -> 'Classification record'.
+    """
+
+    event_id: str
+    bucket: str
+    proposed_bucket: str
+    confidence: float
+    rationale: str
+    topic_tags: List[str]
+    duplicate_of: Optional[str]
+    model: str
+    prompt_version: str
+    prompt_tokens: int
+    completion_tokens: int
+    cost_usd: float
+    raw_model_output: str
+    classified_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())
+
+
+@dataclass
+class ReviewRecord:
+    """One human action on an event.
+
+    Reviews are append-only. Field set matches manifest.md 'Data Model' ->
+    'Review record'.
+    """
+
+    event_id: str
+    reviewer: str
+    action: str
+    final_bucket: str
+    reviewer_rationale: str
+    reviewed_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())
