@@ -0,0 +1,318 @@
+"""SQLite persistence layer for RegIntel Studio.
+
+Uses only the stdlib ``sqlite3`` module. Tables:
+
+- ``events`` — one row per ingested regulatory update.
+- ``classifications`` — APPEND-ONLY; never modified or deleted.
+- ``reviews`` — APPEND-ONLY; never modified or deleted.
+
+This module deliberately exposes NO function that updates or deletes a row
+in ``classifications`` or ``reviews``. Re-classification creates a new row;
+re-review creates a new row.
+"""
+
+from __future__ import annotations
+
+import json
+import sqlite3
+from typing import List, Optional
+
+from .models import ClassificationRecord, EventRecord, ReviewRecord
+
+
+SCHEMA = """
+CREATE TABLE IF NOT EXISTS events (
+    event_id TEXT PRIMARY KEY,
+    source_id TEXT NOT NULL,
+    source_name TEXT NOT NULL,
+    source_type TEXT NOT NULL,
+    source_reliability TEXT NOT NULL,
+    jurisdiction_level TEXT NOT NULL,
+    jurisdiction_name TEXT NOT NULL,
+    detected_at TEXT NOT NULL,
+    effective_date TEXT,
+    is_pending_legislation INTEGER NOT NULL,
+    raw_text TEXT NOT NULL,
+    content_hash TEXT NOT NULL,
+    injection_suspected INTEGER NOT NULL DEFAULT 0,
+    created_at TEXT NOT NULL
+);
+
+CREATE TABLE IF NOT EXISTS classifications (
+    id INTEGER PRIMARY KEY AUTOINCREMENT,
+    event_id TEXT NOT NULL,
+    bucket TEXT NOT NULL,
+    proposed_bucket TEXT NOT NULL,
+    confidence REAL NOT NULL,
+    rationale TEXT NOT NULL,
+    topic_tags TEXT NOT NULL,
+    duplicate_of TEXT,
+    model TEXT NOT NULL,
+    prompt_version TEXT NOT NULL,
+    prompt_tokens INTEGER NOT NULL,
+    completion_tokens INTEGER NOT NULL,
+    cost_usd REAL NOT NULL,
+    raw_model_output TEXT NOT NULL,
+    classified_at TEXT NOT NULL,
+    FOREIGN KEY (event_id) REFERENCES events(event_id)
+);
+
+CREATE TABLE IF NOT EXISTS reviews (
+    id INTEGER PRIMARY KEY AUTOINCREMENT,
+    event_id TEXT NOT NULL,
+    reviewer TEXT NOT NULL,
+    action TEXT NOT NULL,
+    final_bucket TEXT NOT NULL,
+    reviewer_rationale TEXT NOT NULL,
+    reviewed_at TEXT NOT NULL,
+    FOREIGN KEY (event_id) REFERENCES events(event_id)
+);
+
+CREATE INDEX IF NOT EXISTS idx_classifications_event_id ON classifications(event_id);
+CREATE INDEX IF NOT EXISTS idx_reviews_event_id ON reviews(event_id);
+"""
+
+
+def init_db(path: str) -> None:
+    """Open (or create) the SQLite database at ``path`` and ensure schema.
+
+    Idempotent: safe to call repeatedly. Uses ``CREATE TABLE IF NOT EXISTS``.
+    """
+    conn = sqlite3.connect(path)
+    try:
+        conn.executescript(SCHEMA)
+        conn.commit()
+    finally:
+        conn.close()
+
+
+def _connect(path: str) -> sqlite3.Connection:
+    conn = sqlite3.connect(path)
+    conn.row_factory = sqlite3.Row
+    return conn
+
+
+def _row_to_event(row: sqlite3.Row) -> EventRecord:
+    return EventRecord(
+        event_id=row["event_id"],
+        source_id=row["source_id"],
+        source_name=row["source_name"],
+        source_type=row["source_type"],
+        source_reliability=row["source_reliability"],
+        jurisdiction_level=row["jurisdiction_level"],
+        jurisdiction_name=row["jurisdiction_name"],
+        detected_at=row["detected_at"],
+        effective_date=row["effective_date"],
+        is_pending_legislation=bool(row["is_pending_legislation"]),
+        raw_text=row["raw_text"],
+        content_hash=row["content_hash"],
+        injection_suspected=bool(row["injection_suspected"]),
+        created_at=row["created_at"],
+    )
+
+
+def _row_to_classification(row: sqlite3.Row) -> ClassificationRecord:
+    return ClassificationRecord(
+        event_id=row["event_id"],
+        bucket=row["bucket"],
+        proposed_bucket=row["proposed_bucket"],
+        confidence=row["confidence"],
+        rationale=row["rationale"],
+        topic_tags=json.loads(row["topic_tags"]),
+        duplicate_of=row["duplicate_of"],
+        model=row["model"],
+        prompt_version=row["prompt_version"],
+        prompt_tokens=row["prompt_tokens"],
+        completion_tokens=row["completion_tokens"],
+        cost_usd=row["cost_usd"],
+        raw_model_output=row["raw_model_output"],
+        classified_at=row["classified_at"],
+    )
+
+
+def _row_to_review(row: sqlite3.Row) -> ReviewRecord:
+    return ReviewRecord(
+        event_id=row["event_id"],
+        reviewer=row["reviewer"],
+        action=row["action"],
+        final_bucket=row["final_bucket"],
+        reviewer_rationale=row["reviewer_rationale"],
+        reviewed_at=row["reviewed_at"],
+    )
+
+
+def insert_event(path: str, event: EventRecord) -> None:
+    """Insert an event row.
+
+    If ``event_id`` already exists, this raises ``sqlite3.IntegrityError`` —
+    caller should handle or skip. ``created_at`` on the event is used as-is;
+    callers may omit it (the dataclass default populates a UTC timestamp).
+    """
+    conn = _connect(path)
+    try:
+        conn.execute(
+            """
+            INSERT INTO events (
+                event_id, source_id, source_name, source_type, source_reliability,
+                jurisdiction_level, jurisdiction_name, detected_at, effective_date,
+                is_pending_legislation, raw_text, content_hash, injection_suspected,
+                created_at
+            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
+            """,
+            (
+                event.event_id,
+                event.source_id,
+                event.source_name,
+                event.source_type,
+                event.source_reliability,
+                event.jurisdiction_level,
+                event.jurisdiction_name,
+                event.detected_at,
+                event.effective_date,
+                1 if event.is_pending_legislation else 0,
+                event.raw_text,
+                event.content_hash,
+                1 if event.injection_suspected else 0,
+                event.created_at,
+            ),
+        )
+        conn.commit()
+    finally:
+        conn.close()
+
+
+def get_event(path: str, event_id: str) -> Optional[EventRecord]:
+    """Return the event with this id, or ``None`` if not found."""
+    conn = _connect(path)
+    try:
+        row = conn.execute(
+            "SELECT * FROM events WHERE event_id = ?", (event_id,)
+        ).fetchone()
+        return _row_to_event(row) if row else None
+    finally:
+        conn.close()
+
+
+def list_events(path: str) -> List[EventRecord]:
+    """Return all events, ordered by detected_at then event_id."""
+    conn = _connect(path)
+    try:
+        rows = conn.execute(
+            "SELECT * FROM events ORDER BY detected_at, event_id"
+        ).fetchall()
+        return [_row_to_event(r) for r in rows]
+    finally:
+        conn.close()
+
+
+def append_classification(path: str, classification: ClassificationRecord) -> None:
+    """Append a classification row. Never updates existing rows."""
+    conn = _connect(path)
+    try:
+        conn.execute(
+            """
+            INSERT INTO classifications (
+                event_id, bucket, proposed_bucket, confidence, rationale,
+                topic_tags, duplicate_of, model, prompt_version, prompt_tokens,
+                completion_tokens, cost_usd, raw_model_output, classified_at
+            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
+            """,
+            (
+                classification.event_id,
+                classification.bucket,
+                classification.proposed_bucket,
+                classification.confidence,
+                classification.rationale,
+                json.dumps(classification.topic_tags),
+                classification.duplicate_of,
+                classification.model,
+                classification.prompt_version,
+                classification.prompt_tokens,
+                classification.completion_tokens,
+                classification.cost_usd,
+                classification.raw_model_output,
+                classification.classified_at,
+            ),
+        )
+        conn.commit()
+    finally:
+        conn.close()
+
+
+def latest_classification(path: str, event_id: str) -> Optional[ClassificationRecord]:
+    """Return the most recently appended classification for ``event_id``,
+    or ``None`` if no classification exists.
+    """
+    conn = _connect(path)
+    try:
+        row = conn.execute(
+            """
+            SELECT * FROM classifications
+            WHERE event_id = ?
+            ORDER BY id DESC
+            LIMIT 1
+            """,
+            (event_id,),
+        ).fetchone()
+        return _row_to_classification(row) if row else None
+    finally:
+        conn.close()
+
+
+def list_classifications(path: str, event_id: str) -> List[ClassificationRecord]:
+    """Return all classifications for ``event_id`` in append order."""
+    conn = _connect(path)
+    try:
+        rows = conn.execute(
+            """
+            SELECT * FROM classifications
+            WHERE event_id = ?
+            ORDER BY id ASC
+            """,
+            (event_id,),
+        ).fetchall()
+        return [_row_to_classification(r) for r in rows]
+    finally:
+        conn.close()
+
+
+def append_review(path: str, review: ReviewRecord) -> None:
+    """Append a review row. Never updates existing rows."""
+    conn = _connect(path)
+    try:
+        conn.execute(
+            """
+            INSERT INTO reviews (
+                event_id, reviewer, action, final_bucket,
+                reviewer_rationale, reviewed_at
+            ) VALUES (?, ?, ?, ?, ?, ?)
+            """,
+            (
+                review.event_id,
+                review.reviewer,
+                review.action,
+                review.final_bucket,
+                review.reviewer_rationale,
+                review.reviewed_at,
+            ),
+        )
+        conn.commit()
+    finally:
+        conn.close()
+
+
+def list_reviews(path: str, event_id: str) -> List[ReviewRecord]:
+    """Return all reviews for ``event_id`` in append order."""
+    conn = _connect(path)
+    try:
+        rows = conn.execute(
+            """
+            SELECT * FROM reviews
+            WHERE event_id = ?
+            ORDER BY id ASC
+            """,
+            (event_id,),
+        ).fetchall()
+        return [_row_to_review(r) for r in rows]
+    finally:
+        conn.close()
