+"""Runtime configuration for the RegIntel slice.
+
+Values come from environment variables; sensible defaults match the
+manifest. Only stdlib (``os``) is used — no other imports.
+
+Exports:
+
+* ``CONFIDENCE_THRESHOLD`` — float; default ``0.70``. Below this, a
+  classification is recorded as ``needs-review``.
+* ``REGINTEL_DB`` — path to the local SQLite database file; default
+  ``./regintel.db``.
+"""
+
+from __future__ import annotations
+
+import os
+
+DEFAULT_CONFIDENCE_THRESHOLD: float = 0.70
+DEFAULT_DB_PATH: str = "./regintel.db"
+
+
+def _float_env(name: str, default: float) -> float:
+    """Return the float value of ``name`` from the environment, or ``default``.
+
+    An unset or empty variable returns ``default``. A value that cannot be
+    parsed as ``float`` raises ``ValueError`` — the caller (or test) must
+    decide whether to fall back; the manifest does not specify behaviour
+    for malformed thresholds, so we surface the error rather than silently
+    masking it.
+    """
+    raw = os.environ.get(name)
+    if raw is None or raw == "":
+        return default
+    return float(raw)
+
+
+def _str_env(name: str, default: str) -> str:
+    """Return the string value of ``name`` from the environment, or ``default``.
+
+    An unset variable returns ``default``. A present-but-empty variable
+    returns ``""`` (we do not collapse empty to the default — ``dial/client.py``
+    follows the same convention for ``DIAL_MODEL``).
+    """
+    raw = os.environ.get(name)
+    if raw is None:
+        return default
+    return raw
+
+
+def confidence_threshold() -> float:
+    """Return the configured confidence threshold.
+
+    Reads the ``CONFIDENCE_THRESHOLD`` env var on every call so changes
+    during a process lifetime take effect without restart. Default
+    ``0.70`` when unset or empty.
+    """
+    return _float_env("CONFIDENCE_THRESHOLD", DEFAULT_CONFIDENCE_THRESHOLD)
+
+
+def db_path() -> str:
+    """Return the configured SQLite database file path.
+
+    Reads the ``REGINTEL_DB`` env var on every call. Default
+    ``./regintel.db`` when unset.
+    """
+    return _str_env("REGINTEL_DB", DEFAULT_DB_PATH)
+
+
+# Module-level constants used by callers that want the "compiled once"
+# flavour (e.g. CLI scripts that capture the value at startup).
+CONFIDENCE_THRESHOLD: float = _float_env(
+    "CONFIDENCE_THRESHOLD", DEFAULT_CONFIDENCE_THRESHOLD
+)
+REGINTEL_DB: str = _str_env("REGINTEL_DB", DEFAULT_DB_PATH)
+
+
+__all__ = [
+    "CONFIDENCE_THRESHOLD",
+    "REGINTEL_DB",
+    "DEFAULT_CONFIDENCE_THRESHOLD",
+    "DEFAULT_DB_PATH",
+    "confidence_threshold",
+    "db_path",
+]
