+"""Domain dataclasses for the RegIntel Monitoring + Relevance slice.
+
+Field names follow the manifest's "Data Model" section exactly:
+
+* ``EventRecord`` — one per ingested regulatory update.
+* ``ClassificationRecord`` — one per classification of an event
+  (re-classification appends; never overwrites).
+* ``ReviewRecord`` — one per human action on a classification.
+
+Only stdlib ``dataclasses`` are used so the package has no third-party
+runtime imports. ``Optional[...]`` fields default to ``None``; floats use
+``0.0`` defaults; ints use ``0`` defaults; bools use ``False``; strings
+use ``""``; lists use empty ``list`` factories so each instance owns its
+own list.
+"""
+
+from __future__ import annotations
+
+from dataclasses import dataclass, field
+from typing import Optional
+
+
+@dataclass
+class EventRecord:
+    """A single detected regulatory update.
+
+    See manifest "Data Model — Event record". One per ingested update.
+    """
+
+    event_id: str = ""
+    source_id: str = ""
+    source_name: str = ""
+    source_type: str = ""
+    source_reliability: str = ""
+    jurisdiction_level: str = ""
+    jurisdiction_name: str = ""
+    detected_at: str = ""
+    effective_date: Optional[str] = None
+    is_pending_legislation: bool = False
+    raw_text: str = ""
+    content_hash: str = ""
+    injection_suspected: bool = False
+    created_at: str = ""
+
+
+@dataclass
+class ClassificationRecord:
+    """One classification of an event.
+
+    See manifest "Data Model — Classification record". Re-classification
+    appends a new record; the original is never modified.
+    """
+
+    event_id: str = ""
+    bucket: str = ""
+    proposed_bucket: str = ""
+    confidence: float = 0.0
+    rationale: str = ""
+    topic_tags: list[str] = field(default_factory=list)
+    duplicate_of: Optional[str] = None
+    model: str = ""
+    prompt_version: str = ""
+    prompt_tokens: int = 0
+    completion_tokens: int = 0
+    cost_usd: float = 0.0
+    raw_model_output: str = ""
+    classified_at: str = ""
+
+
+@dataclass
+class ReviewRecord:
+    """One human review action against an event.
+
+    See manifest "Data Model — Review record". One per human action.
+    """
+
+    event_id: str = ""
+    reviewer: str = ""
+    action: str = ""
+    final_bucket: str = ""
+    reviewer_rationale: str = ""
+    reviewed_at: str = ""
+
+
+__all__ = ["EventRecord", "ClassificationRecord", "ReviewRecord"]
