+"""SQLite-backed store for the RegIntel slice.
+
+Uses only the Python standard library (``sqlite3``). The database holds
+three append-mostly tables:
+
+* ``events`` — one row per ingested regulatory update.
+* ``classifications`` — one row per classification of an event. Re-
+  classification appends; rows are **never updated, never deleted**.
+* ``reviews`` — one row per human review action. Rows are **never
+  updated, never deleted**.
+
+Events are inserted once and may be looked up or listed, but never
+deleted through this module — the manifest's governance non-negotiable
+is that nothing is silently dropped.
+
+All helpers return plain dicts (or lists of dicts) keyed by the manifest
+field names so callers can pass them straight to the dataclasses in
+``regintel.models``.
+"""
+
+from __future__ import annotations
+
+import sqlite3
+from contextlib import contextmanager
+from typing import Any, Iterator, Optional
+
+# ---------------------------------------------------------------------------
+# Schema
+# ---------------------------------------------------------------------------
+
+_SCHEMA_SQL = """
+CREATE TABLE IF NOT EXISTS events (
+    event_id                TEXT PRIMARY KEY,
+    source_id               TEXT NOT NULL,
+    source_name             TEXT NOT NULL,
+    source_type             TEXT NOT NULL,
+    source_reliability      TEXT NOT NULL,
+    jurisdiction_level      TEXT NOT NULL,
+    jurisdiction_name       TEXT NOT NULL,
+    detected_at             TEXT NOT NULL,
+    effective_date          TEXT,
+    is_pending_legislation  INTEGER NOT NULL DEFAULT 0,
+    raw_text                TEXT NOT NULL,
+    content_hash            TEXT NOT NULL,
+    injection_suspected     INTEGER NOT NULL DEFAULT 0,
+    created_at              TEXT NOT NULL
+);
+
+CREATE TABLE IF NOT EXISTS classifications (
+    classification_id  INTEGER PRIMARY KEY AUTOINCREMENT,
+    event_id           TEXT NOT NULL,
+    bucket             TEXT NOT NULL,
+    proposed_bucket    TEXT NOT NULL,
+    confidence         REAL NOT NULL,
+    rationale          TEXT NOT NULL,
+    topic_tags         TEXT NOT NULL,
+    duplicate_of       TEXT,
+    model              TEXT NOT NULL,
+    prompt_version     TEXT NOT NULL,
+    prompt_tokens      INTEGER NOT NULL,
+    completion_tokens  INTEGER NOT NULL,
+    cost_usd           REAL NOT NULL,
+    raw_model_output   TEXT NOT NULL,
+    classified_at      TEXT NOT NULL,
+    FOREIGN KEY (event_id) REFERENCES events(event_id)
+);
+
+CREATE TABLE IF NOT EXISTS reviews (
+    review_id           INTEGER PRIMARY KEY AUTOINCREMENT,
+    event_id            TEXT NOT NULL,
+    reviewer            TEXT NOT NULL,
+    action              TEXT NOT NULL,
+    final_bucket        TEXT NOT NULL,
+    reviewer_rationale  TEXT NOT NULL,
+    reviewed_at         TEXT NOT NULL,
+    FOREIGN KEY (event_id) REFERENCES events(event_id)
+);
+"""
+
+# Columns used when hydrating a Classification row back into a dict.
+_CLASSIFICATION_COLUMNS = (
+    "event_id",
+    "bucket",
+    "proposed_bucket",
+    "confidence",
+    "rationale",
+    "topic_tags",
+    "duplicate_of",
+    "model",
+    "prompt_version",
+    "prompt_tokens",
+    "completion_tokens",
+    "cost_usd",
+    "raw_model_output",
+    "classified_at",
+)
+
+# Columns used when hydrating a Review row back into a dict.
+_REVIEW_COLUMNS = (
+    "event_id",
+    "reviewer",
+    "action",
+    "final_bucket",
+    "reviewer_rationale",
+    "reviewed_at",
+)
+
+# Columns used when hydrating an Event row back into a dict.
+_EVENT_COLUMNS = (
+    "event_id",
+    "source_id",
+    "source_name",
+    "source_type",
+    "source_reliability",
+    "jurisdiction_level",
+    "jurisdiction_name",
+    "detected_at",
+    "effective_date",
+    "is_pending_legislation",
+    "raw_text",
+    "content_hash",
+    "injection_suspected",
+    "created_at",
+)
+
+
+# ---------------------------------------------------------------------------
+# Connection / schema management
+# ---------------------------------------------------------------------------
+
+
+def init_db(path: str) -> None:
+    """Create the database file at ``path`` and ensure all tables exist.
+
+    Safe to call on an existing database — every ``CREATE TABLE`` uses
+    ``IF NOT EXISTS``. Foreign keys are enabled for the lifetime of each
+    connection opened by the helpers below.
+    """
+    conn = sqlite3.connect(path)
+    try:
+        conn.executescript(_SCHEMA_SQL)
+        conn.commit()
+    finally:
+        conn.close()
+
+
+@contextmanager
+def _connect(path: str) -> Iterator[sqlite3.Connection]:
+    """Yield a connection with row factory set and FK enforcement on.
+
+    Callers commit on success and close on exit (the ``with`` statement
+    handles close; commit is explicit at each helper).
+    """
+    conn = sqlite3.connect(path)
+    try:
+        conn.row_factory = sqlite3.Row
+        conn.execute("PRAGMA foreign_keys = ON")
+        yield conn
+    finally:
+        conn.close()
+
+
+def _row_to_dict(row: sqlite3.Row) -> dict[str, Any]:
+    """Convert a ``sqlite3.Row`` to a plain dict."""
+    return {key: row[key] for key in row.keys()}
+
+
+# ---------------------------------------------------------------------------
+# Events
+# ---------------------------------------------------------------------------
+
+
+def insert_event(path: str, event: dict[str, Any]) -> None:
+    """Insert a single event row.
+
+    ``event`` is a mapping with the manifest's event-record field names.
+    Booleans (``is_pending_legislation``, ``injection_suspected``) are
+    coerced to ``0``/``1`` for SQLite. A row whose ``event_id`` already
+    exists raises ``sqlite3.IntegrityError`` — callers that want
+    idempotent re-ingest must catch it and treat that as success.
+    """
+    payload = (
+        event["event_id"],
+        event["source_id"],
+        event["source_name"],
+        event["source_type"],
+        event["source_reliability"],
+        event["jurisdiction_level"],
+        event["jurisdiction_name"],
+        event["detected_at"],
+        event.get("effective_date"),
+        1 if event.get("is_pending_legislation") else 0,
+        event["raw_text"],
+        event["content_hash"],
+        1 if event.get("injection_suspected") else 0,
+        event["created_at"],
+    )
+    with _connect(path) as conn:
+        conn.execute(
+            """
+            INSERT INTO events (
+                event_id, source_id, source_name, source_type,
+                source_reliability, jurisdiction_level, jurisdiction_name,
+                detected_at, effective_date, is_pending_legislation,
+                raw_text, content_hash, injection_suspected, created_at
+            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
+            """,
+            payload,
+        )
+        conn.commit()
+
+
+def get_event(path: str, event_id: str) -> Optional[dict[str, Any]]:
+    """Return the event with the given ``event_id``, or ``None`` if absent."""
+    with _connect(path) as conn:
+        row = conn.execute(
+            "SELECT * FROM events WHERE event_id = ?", (event_id,)
+        ).fetchone()
+    if row is None:
+        return None
+    d = _row_to_dict(row)
+    # Coerce integer-flag columns back to bool for caller convenience.
+    d["is_pending_legislation"] = bool(d["is_pending_legislation"])
+    d["injection_suspected"] = bool(d["injection_suspected"])
+    return d
+
+
+def list_events(path: str) -> list[dict[str, Any]]:
+    """Return every event row, ordered by ``detected_at`` then ``event_id``."""
+    with _connect(path) as conn:
+        rows = conn.execute(
+            "SELECT * FROM events ORDER BY detected_at ASC, event_id ASC"
+        ).fetchall()
+    out: list[dict[str, Any]] = []
+    for row in rows:
+        d = _row_to_dict(row)
+        d["is_pending_legislation"] = bool(d["is_pending_legislation"])
+        d["injection_suspected"] = bool(d["injection_suspected"])
+        out.append(d)
+    return out
+
+
+# ---------------------------------------------------------------------------
+# Classifications (append-only — no update, no delete)
+# ---------------------------------------------------------------------------
+
+
+def append_classification(path: str, classification: dict[str, Any]) -> int:
+    """Append a classification row. Returns the new ``classification_id``.
+
+    ``classification`` is a mapping with the manifest's classification-
+    record field names. ``topic_tags`` may be a list or a JSON-encoded
+    string; the value is stored as text and round-tripped through JSON
+    on read so callers always see a list.
+
+    This module exposes no function that updates or deletes a
+    classification row; that is intentional — see the manifest's
+    "Governance non-negotiable".
+    """
+    topic_tags = classification.get("topic_tags", [])
+    if isinstance(topic_tags, list):
+        import json
+
+        topic_tags_text = json.dumps(topic_tags)
+    else:
+        topic_tags_text = str(topic_tags)
+
+    payload = (
+        classification["event_id"],
+        classification["bucket"],
+        classification.get("proposed_bucket", ""),
+        float(classification.get("confidence", 0.0)),
+        classification.get("rationale", ""),
+        topic_tags_text,
+        classification.get("duplicate_of"),
+        classification.get("model", ""),
+        classification.get("prompt_version", ""),
+        int(classification.get("prompt_tokens", 0)),
+        int(classification.get("completion_tokens", 0)),
+        float(classification.get("cost_usd", 0.0)),
+        classification.get("raw_model_output", ""),
+        classification.get("classified_at", ""),
+    )
+    with _connect(path) as conn:
+        cur = conn.execute(
+            """
+            INSERT INTO classifications (
+                event_id, bucket, proposed_bucket, confidence, rationale,
+                topic_tags, duplicate_of, model, prompt_version,
+                prompt_tokens, completion_tokens, cost_usd,
+                raw_model_output, classified_at
+            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
+            """,
+            payload,
+        )
+        conn.commit()
+        return int(cur.lastrowid)
+
+
+def _hydrate_classification(row: sqlite3.Row) -> dict[str, Any]:
+    """Convert a classification row to a dict, decoding ``topic_tags`` to list."""
+    d = _row_to_dict(row)
+    raw_tags = d.pop("topic_tags", "")
+    import json
+
+    if raw_tags == "" or raw_tags is None:
+        d["topic_tags"] = []
+    else:
+        try:
+            d["topic_tags"] = json.loads(raw_tags)
+            if not isinstance(d["topic_tags"], list):
+                d["topic_tags"] = []
+        except (ValueError, TypeError):
+            d["topic_tags"] = []
+    return d
+
+
+def latest_classification(path: str, event_id: str) -> Optional[dict[str, Any]]:
+    """Return the most recent classification for ``event_id`` or ``None``.
+
+    "Most recent" means the highest ``classification_id`` (insertion
+    order), so re-classifications supersede each other for *display*
+    purposes only — every classification row is still preserved.
+    """
+    with _connect(path) as conn:
+        row = conn.execute(
+            """
+            SELECT * FROM classifications
+            WHERE event_id = ?
+            ORDER BY classification_id DESC
+            LIMIT 1
+            """,
+            (event_id,),
+        ).fetchone()
+    if row is None:
+        return None
+    return _hydrate_classification(row)
+
+
+def list_classifications(path: str, event_id: str) -> list[dict[str, Any]]:
+    """Return every classification for ``event_id``, oldest first."""
+    with _connect(path) as conn:
+        rows = conn.execute(
+            """
+            SELECT * FROM classifications
+            WHERE event_id = ?
+            ORDER BY classification_id ASC
+            """,
+            (event_id,),
+        ).fetchall()
+    return [_hydrate_classification(row) for row in rows]
+
+
+# ---------------------------------------------------------------------------
+# Reviews (append-only — no update, no delete)
+# ---------------------------------------------------------------------------
+
+
+def append_review(path: str, review: dict[str, Any]) -> int:
+    """Append a review row. Returns the new ``review_id``.
+
+    This module exposes no function that updates or deletes a review row;
+    that is intentional.
+    """
+    payload = (
+        review["event_id"],
+        review.get("reviewer", ""),
+        review.get("action", ""),
+        review.get("final_bucket", ""),
+        review.get("reviewer_rationale", ""),
+        review.get("reviewed_at", ""),
+    )
+    with _connect(path) as conn:
+        cur = conn.execute(
+            """
+            INSERT INTO reviews (
+                event_id, reviewer, action, final_bucket,
+                reviewer_rationale, reviewed_at
+            ) VALUES (?, ?, ?, ?, ?, ?)
+            """,
+            payload,
+        )
+        conn.commit()
+        return int(cur.lastrowid)
+
+
+def list_reviews(path: str, event_id: str) -> list[dict[str, Any]]:
+    """Return every review row for ``event_id``, oldest first."""
+    with _connect(path) as conn:
+        rows = conn.execute(
+            """
+            SELECT * FROM reviews
+            WHERE event_id = ?
+            ORDER BY review_id ASC
+            """,
+            (event_id,),
+        ).fetchall()
+    return [_row_to_dict(row) for row in rows]
+
+
+__all__ = [
+    "init_db",
+    "insert_event",
+    "get_event",
+    "list_events",
+    "append_classification",
+    "latest_classification",
+    "list_classifications",
+    "append_review",
+    "list_reviews",
+]
