+      </div>
+      <div class="metric-card">
+        <div class="label">Cost / Event</div>
+        <div class="value" id="metric-cost-per-event">&mdash;</div>
+      </div>
+    </section>
+    <div class="toolbar">
+      <label for="bucket-filter">Bucket</label>
+      <select id="bucket-filter" aria-label="Filter by bucket">
+        <option value="all">All</option>
+        <option value="relevant">relevant</option>
+        <option value="irrelevant">irrelevant</option>
+        <option value="duplicate">duplicate</option>
+        <option value="needs-review">needs-review</option>
+      </select>
+      <span class="status-message" id="status-message"></span>
+    </div>
+    <section class="queue-panel" aria-label="Review queue">
+      <div class="queue-table-wrap">
+        <table class="queue">
+          <thead>
+            <tr>
+              <th>Source</th>
+              <th>Jurisdiction</th>
+              <th>Detected</th>
+              <th>Bucket</th>
+              <th class="num">Confidence</th>
+              <th>Injection</th>
+              <th>Rationale</th>
+              <th>Review Status</th>
+              <th>Actions</th>
+            </tr>
+          </thead>
+          <tbody id="queue-body">
+            <tr class="empty-row"><td colspan="9">Loading&hellip;</td></tr>
+          </tbody>
+        </table>
+      </div>
+    </section>
+  </main><script>
+  (function () {
+    "use strict";
+    var BUCKETS = ["relevant", "irrelevant", "duplicate", "needs-review"];
+    var BUCKET_LABEL = {
+      "relevant": "relevant",
+      "irrelevant": "irrelevant",
+      "duplicate": "duplicate",
+      "needs-review": "needs-review"
+    };
+    var rowsByEventId = Object.create(null);
+    var currentFilter = "all";
+
+    function el(tag, attrs, children) {
+      var node = document.createElement(tag);
+      if (attrs) {
+        Object.keys(attrs).forEach(function (key) {
+          var value = attrs[key];
+          if (value === null || value === undefined || value === false) return;
+          if (key === "class") node.className = value;
+          else if (key === "text") node.textContent = value;
+          else if (key === "dataset") {
+            Object.keys(value).forEach(function (k) { node.dataset[k] = value[k]; });
+          } else if (key.indexOf("on") === 0 && typeof value === "function") {
+            node.addEventListener(key.slice(2), value);
+          } else {
+            node.setAttribute(key, value);
+          }
+        });
+      }
+      if (children) {
+        (Array.isArray(children) ? children : [children]).forEach(function (child) {
+          if (child === null || child === undefined || child === false) return;
+          if (typeof child === "string") {
+            node.appendChild(document.createTextNode(child));
+          } else {
+            node.appendChild(child);
+          }
+        });
+      }
+      return node;
+    }
+
+    function bucketClass(bucket) {
+      return "bucket-cell bucket-" + bucket;
+    }
+    function statusClass(status) {
+      if (status === "approved" || status === "overridden" || status === "pending") {
+        return "status-pill " + status;
+      }
+      return "status-pill pending";
+    }
+    function setStatus(message, isError) {
+      var node = document.getElementById("status-message");
+      node.textContent = message || "";
+      if (isError) node.classList.add("error");
+      else node.classList.remove("error");
+    }
+    function buildRationaleCell(text) {
+      var wrapper = el("div", { class: "rationale-cell" });
+      var textNode = el("div", {
+        class: "rationale-text",
+        title: "Click to expand / collapse"
+      }, text || "");
+      var toggle = el("button", {
+        type: "button",
+        class: "rationale-toggle",
+        "aria-label": "Expand rationale"
+      }, "expand");
+      function syncToggle() {
+        toggle.textContent = textNode.classList.contains("expanded") ? "collapse" : "expand";
+      }
+      textNode.addEventListener("click", function () {
+        textNode.classList.toggle("expanded");
+        syncToggle();
+      });
+      toggle.addEventListener("click", function (event) {
+        event.stopPropagation();
+        textNode.classList.toggle("expanded");
+        syncToggle();
+      });
+      wrapper.appendChild(textNode);
+      wrapper.appendChild(toggle);
+      return wrapper;
+    }
+
+    function renderRow(entry) {
+      var eventId = entry.event_id;
+      var bucket = entry.bucket;
+      var reviewStatus = entry.review_status || "pending";
+      var finalBucket = entry.final_bucket || bucket;
+      var injection = !!entry.injection_suspected;
+      var confidence = Number(entry.confidence || 0);
+
+      var tr = el("tr", { dataset: { eventId: eventId } });
+      tr.appendChild(el("td", { text: entry.source_id || "" }));
+      tr.appendChild(el("td", { text: entry.jurisdiction_name || "" }));
+      tr.appendChild(el("td", { text: entry.detected_at || "" }));
+
+      var bucketCell = el("td");
+      bucketCell.appendChild(el("span", {
+        class: bucketClass(bucket),
+        text: BUCKET_LABEL[bucket] || bucket
+      }));
+      if (reviewStatus === "overridden" && finalBucket && finalBucket !== bucket) {
+        bucketCell.appendChild(document.createTextNode(" "));
+        bucketCell.appendChild(el("span", {
+          class: bucketClass(finalBucket),
+          text: "\u2192 " + (BUCKET_LABEL[finalBucket] || finalBucket)
+        }));
+      }
+      tr.appendChild(bucketCell);
+
+      tr.appendChild(el("td", { class: "num", text: confidence.toFixed(2) }));
+
+      tr.appendChild(el("td", null, [
+        el("span", {
+          class: "injection-flag " + (injection ? "" : "none"),
+          text: injection ? "flagged" : "none"
+        })
+      ]));
+
+      tr.appendChild(el("td", null, buildRationaleCell(entry.rationale || "")));
+
+      var statusCell = el("td");
+      statusCell.appendChild(el("span", {
+        class: statusClass(reviewStatus),
+        text: reviewStatus
+      }));
+      if (reviewStatus === "overridden" && finalBucket) {
+        statusCell.appendChild(document.createTextNode(" "));
+        statusCell.appendChild(el("span", {
+          class: "status-pill " + finalBucket,
+          text: finalBucket
+        }));
+      }
+      tr.appendChild(statusCell);
+
+      tr.appendChild(buildActionsCell(entry));
+      return tr;
+    }
+
+    function buildActionsCell(entry) {
+      var eventId = entry.event_id;
+      var actionsCell = el("td");
+      var row = el("div", { class: "row-actions" });
+      var approveBtn = el("button", {
+        type: "button",
+        class: "approve-btn",
+        "aria-label": "Approve event " + eventId
+      }, "Approve");
+      var overrideBtn = el("button", {
+        type: "button",
+        class: "override-btn",
+        "aria-label": "Override event " + eventId
+      }, "Override");
+      var topRow = el("div", { class: "action-row" }, [approveBtn, overrideBtn]);
+      row.appendChild(topRow);
+
+      var overrideForm = buildOverrideForm(entry);
+      row.appendChild(overrideForm);
+
+      approveBtn.addEventListener("click", function () {
+        submitReview(entry, overrideForm, {
+          action: "approve",
+          final_bucket: entry.bucket,
+          reviewer: "web-reviewer",
+          reviewer_rationale: "Approved via RegIntel review portal."
+        });
+      });
+      overrideBtn.addEventListener("click", function () {
+        overrideForm.classList.toggle("visible");
+        if (overrideForm.classList.contains("visible")) {
+          var select = overrideForm.querySelector("select");
+          if (select && !select.value) select.value = entry.bucket;
+          var firstInput = overrideForm.querySelector("input, select, textarea");
+          if (firstInput) firstInput.focus();
+        }
+      });
+
+      actionsCell.appendChild(row);
+      return actionsCell;
+    }
+
+    function buildOverrideForm(entry) {
+      var form = el("div", { class: "override-form" });
+      form.appendChild(el("label", { for: "override-bucket-" + entry.event_id }, "Final bucket"));
+      var select = el("select", {
+        id: "override-bucket-" + entry.event_id,
+        required: "required"
+      });
+      BUCKETS.forEach(function (b) {
+        var option = el("option", { value: b }, BUCKET_LABEL[b] || b);
+        if (b === entry.bucket) option.selected = true;
+        select.appendChild(option);
+      });
+      form.appendChild(select);
+
+      form.appendChild(el("label", { for: "override-reviewer-" + entry.event_id }, "Reviewer"));
+      var reviewerInput = el("input", {
+        type: "text",
+        id: "override-reviewer-" + entry.event_id,
+        placeholder: "reviewer id",
+        required: "required"
+      });
+      form.appendChild(reviewerInput);
+
+      form.appendChild(el("label", { for: "override-rationale-" + entry.event_id }, "Rationale"));
+      var rationaleInput = el("textarea", {
+        id: "override-rationale-" + entry.event_id,
+        placeholder: "Why are you overriding?",
+        required: "required"
+      });
+      form.appendChild(rationaleInput);
+
+      var errorNode = el("div", { class: "form-error" });
+      form.appendChild(errorNode);
+
+      var buttons = el("div", { class: "form-buttons" });
+      var submitBtn = el("button", { type: "button", class: "approve-btn" }, "Submit override");
+      var cancelBtn = el("button", { type: "button" }, "Cancel");
+      buttons.appendChild(submitBtn);
+      buttons.appendChild(cancelBtn);
+      form.appendChild(buttons);
+
+      cancelBtn.addEventListener("click", function () {
+        form.classList.remove("visible");
+        reviewerInput.value = "";
+        rationaleInput.value = "";
+        errorNode.textContent = "";
+      });
+      submitBtn.addEventListener("click", function () {
+        errorNode.textContent = "";
+        if (!select.value) { errorNode.textContent = "Pick a final bucket."; return; }
+        if (!reviewerInput.value.trim()) { errorNode.textContent = "Reviewer is required."; return; }
+        if (!rationaleInput.value.trim()) { errorNode.textContent = "Rationale is required."; return; }
+        submitReview(entry, form, {
+          action: "override",
+          final_bucket: select.value,
+          reviewer: reviewerInput.value.trim(),
+          reviewer_rationale: rationaleInput.value.trim()
+        });
+      });
+
+      return form;
+    }
+
+    function fetchJSON(url, options) {
+      return fetch(url, options).then(function (response) {
+        if (!response.ok) {
+          return response.text().then(function (body) {
+            throw new Error("HTTP " + response.status + " for " + url + ": " + body);
+          });
+        }
+        return response.json();
+      });
+    }
+
+    function upsertRow(entry) {
+      var tbody = document.getElementById("queue-body");
+      var eventId = entry.event_id;
+      var existingTr = rowsByEventId[eventId];
+      var newTr = renderRow(entry);
+      if (existingTr && existingTr.parentNode === tbody) {
+        tbody.replaceChild(newTr, existingTr);
+      } else {
+        var placeholder = tbody.querySelector(".empty-row");
+        if (placeholder && tbody.children.length === 1) {
+          tbody.removeChild(placeholder);
+        }
+        tbody.appendChild(newTr);
+      }
+      rowsByEventId[eventId] = newTr;
+    }
+
+    function applyFilter() {
+      var tbody = document.getElementById("queue-body");
+      var rows = tbody.querySelectorAll("tr");
+      rows.forEach(function (tr) {
+        if (tr.classList.contains("empty-row")) {
+          tr.style.display = "";
+          return;
+        }
+        var bucketCell = tr.querySelector(".bucket-cell");
+        if (!bucketCell) return;
+        var bucket = bucketCell.className.split(/\s+/).filter(function (c) {
+          return c.indexOf("bucket-") === 0 && c !== "bucket-cell";
+        })[0];
+        var bucketName = bucket ? bucket.replace("bucket-", "") : "";
+        if (currentFilter === "all" || bucketName === currentFilter) {
+          tr.style.display = "";
+        } else {
+          tr.style.display = "none";
+        }
+      });
+    }
+
+    function loadQueue() {
+      setStatus("Loading queue\u2026", false);
+      return fetchJSON("/queue").then(function (entries) {
+        if (!Array.isArray(entries)) {
+          setStatus("Unexpected /queue response", true);
+          return;
+        }
+        entries.forEach(function (entry) { upsertRow(entry); });
+        applyFilter();
+        setStatus(
+          "Loaded " + entries.length + " event" + (entries.length === 1 ? "" : "s") + ".",
+          false
+        );
+      }).catch(function (err) {
+        setStatus("Failed to load queue: " + err.message, true);
+      });
+    }
+
+    function setMetric(id, value) {
+      var node = document.getElementById(id);
+      if (!node) return;
+      if (value === null || value === undefined) {
+        node.textContent = "\u2014";
+      } else if (id === "metric-cost-per-event") {
+        node.textContent = "$" + Number(value).toFixed(6);
+      } else {
+        node.textContent = String(value);
+      }
+    }
+
+    function loadMetrics() {
+      return fetchJSON("/metrics").then(function (metrics) {
+        if (!metrics || typeof metrics !== "object") return;
+        setMetric("metric-events", metrics.events);
+        BUCKETS.forEach(function (bucket) {
+          setMetric("metric-" + bucket, metrics[bucket]);
+        });
+        setMetric("metric-cost-per-event", metrics.cost_per_event_usd);
+      }).catch(function (err) {
+        setStatus("Failed to load metrics: " + err.message, true);
+      });
+    }
+
+    function submitReview(entry, overrideForm, payload) {
+      setStatus("Saving review\u2026", false);
+      var buttons = overrideForm.querySelectorAll("button");
+      buttons.forEach(function (b) { b.disabled = true; });
+      var tr = rowsByEventId[entry.event_id];
+      if (tr) {
+        var actionRow = tr.querySelector(".action-row");
+        if (actionRow) {
+          actionRow.querySelectorAll("button").forEach(function (b) { b.disabled = true; });
+        }
+      }
+      return fetchJSON("/events/" + encodeURIComponent(entry.event_id) + "/review", {
+        method: "POST",
+        headers: { "Content-Type": "application/json" },
+        body: JSON.stringify(payload)
+      }).then(function (result) {
+        setStatus("Saved " + payload.action + " for " + entry.event_id + ".", false);
+        if (overrideForm) {
+          overrideForm.classList.remove("visible");
+          var reviewerInput = overrideForm.querySelector('input[type="text"]');
+          var rationaleInput = overrideForm.querySelector("textarea");
+          if (reviewerInput) reviewerInput.value = "";
+          if (rationaleInput) rationaleInput.value = "";
+          var errorNode = overrideForm.querySelector(".form-error");
+          if (errorNode) errorNode.textContent = "";
+        }
+        return fetchJSON("/queue").then(function (entries) {
+          if (Array.isArray(entries)) {
+            entries.forEach(function (e) { upsertRow(e); });
+            applyFilter();
+          }
+          return result;
+        });
+      }).catch(function (err) {
+        setStatus("Review failed: " + err.message, true);
+        buttons.forEach(function (b) { b.disabled = false; });
+        if (tr) {
+          var actionRow = tr.querySelector(".action-row");
+          if (actionRow) {
+            actionRow.querySelectorAll("button").forEach(function (b) { b.disabled = false; });
+          }
+        }
+      });
+    }
+
+    function init() {
+      var filter = document.getElementById("bucket-filter");
+      filter.addEventListener("change", function () {
+        currentFilter = filter.value || "all";
+        applyFilter();
+      });
+      loadMetrics();
+      loadQueue();
+    }
+
+    if (document.readyState === "loading") {
+      document.addEventListener("DOMContentLoaded", init);
+    } else {
+      init();
+    }
+  })();
+  </script>
+</body>
