+          container.appendChild(el("p", {
+            id: "metrics-status",
+            text: "Metrics unavailable (" + error.message + ")."
+          }));
+        });
+    }
+
+    // -- rationale cell (truncated, expandable) --------------------------
+
+    function rationaleCell(text) {
+      var full = text || "";
+      var td = el("td", { "class": "rationale" });
+
+      if (full.length > RATIONALE_LIMIT) {
+        var span = el("span", {
+          "class": "rationale-text",
+          text: full.slice(0, RATIONALE_LIMIT) + "\u2026"
+        });
+        var toggle = el("button", {
+          type: "button",
+          "class": "expand-btn",
+          "aria-expanded": "false",
+          "aria-label": "Expand rationale to show the full text",
+          text: "More"
+        });
+        toggle.addEventListener("click", function () {
+          var expanded = toggle.getAttribute("aria-expanded") === "true";
+          if (expanded) {
+            span.textContent = full.slice(0, RATIONALE_LIMIT) + "\u2026";
+            toggle.textContent = "More";
+            toggle.setAttribute("aria-expanded", "false");
+            toggle.setAttribute(
+              "aria-label", "Expand rationale to show the full text"
+            );
+          } else {
+            span.textContent = full;
+            toggle.textContent = "Less";
+            toggle.setAttribute("aria-expanded", "true");
+            toggle.setAttribute(
+              "aria-label", "Collapse rationale to show the truncated text"
+            );
+          }
+        });
+        td.appendChild(span);
+        td.appendChild(document.createTextNode(" "));
+        td.appendChild(toggle);
+      } else {
+        td.textContent = full;
+      }
+      return td;
+    }
+
+    // -- review forms (Approve / Override) -------------------------------
+
+    function reviewForm(row, mode) {
+      // mode: "approve" keeps the current bucket; "override" offers a
+      // select of the four buckets plus reviewer and rationale inputs.
+      var currentBucket = displayBucket(row);
+
+      var form = el("form", { "class": "review-form " + mode + "-form" });
+      form.hidden = true;
+
+      var fieldset = el("fieldset");
+      fieldset.appendChild(el("legend", {
+        text: (mode === "approve" ? "Approve " : "Override ") +
+              (row.source_id || row.event_id)
+      }));
+
+      var bucketSelect = null;
+      if (mode === "override") {
+        bucketSelect = el("select", {
+          name: "bucket",
+          id: "override-bucket-" + row.event_id,
+          "aria-label": "New bucket"
+        });
+        BUCKETS.forEach(function (bucket) {
+          var option = el("option", { value: bucket, text: bucket });
+          if (bucket === currentBucket) option.setAttribute("selected", "selected");
+          bucketSelect.appendChild(option);
+        });
+        var bucketLabel = el("label", {
+          for: "override-bucket-" + row.event_id,
+          text: "Bucket"
+        });
+        var bucketWrap = el("div", {});
+        bucketWrap.appendChild(bucketLabel);
+        bucketWrap.appendChild(bucketSelect);
+        fieldset.appendChild(bucketWrap);
+      }
+
+      // Both reviewer and rationale carry the `required` attribute so a
+      // browser blocks submission (and sends no request) when either is
+      // empty; the submit handler re-checks as a belt-and-braces guard.
+      var reviewerInput = el("input", {
+        type: "text",
+        name: "reviewer",
+        id: mode + "-reviewer-" + row.event_id,
+        required: "",
+        autocomplete: "off"
+      });
+      var reviewerLabel = el("label", {
+        for: mode + "-reviewer-" + row.event_id,
+        text: "Reviewer"
+      });
+      var reviewerWrap = el("div", {});
+      reviewerWrap.appendChild(reviewerLabel);
+      reviewerWrap.appendChild(reviewerInput);
+      fieldset.appendChild(reviewerWrap);
+
+      var rationaleInput = el("textarea", {
+        name: "rationale",
+        id: mode + "-rationale-" + row.event_id,
+        required: "",
+        rows: "2"
+      });
+      var rationaleLabel = el("label", {
+        for: mode + "-rationale-" + row.event_id,
+        text: "Rationale"
+      });
+      var rationaleWrap = el("div", {});
+      rationaleWrap.appendChild(rationaleLabel);
+      rationaleWrap.appendChild(rationaleInput);
+      fieldset.appendChild(rationaleWrap);
+
+      var errorBox = el("p", {
+        "class": "form-error",
+        role: "alert",
+        hidden: "hidden"
+      });
+
+      var submitBtn = el("button", {
+        type: "submit",
+        "class": "submit-btn",
+        text: mode === "approve" ? "Confirm approval" : "Confirm override"
+      });
+      var cancelBtn = el("button", { type: "button", "class": "cancel-btn", text: "Cancel" });
+
+      var actions = el("div", { "class": "form-actions" });
+      actions.appendChild(submitBtn);
+      actions.appendChild(cancelBtn);
+      fieldset.appendChild(actions);
+      fieldset.appendChild(errorBox);
+      form.appendChild(fieldset);
+
+      function hide() { form.hidden = true; errorBox.hidden = true; }
+      cancelBtn.addEventListener("click", hide);
+
+      form.addEventListener("submit", function (event) {
+        event.preventDefault();
+        errorBox.hidden = true;
+        errorBox.textContent = "";
+
+        var reviewer = reviewerInput.value.trim();
+        var rationale = rationaleInput.value.trim();
+        var bucket = mode === "override"
+          ? bucketSelect.value
+          : currentBucket;
+
+        // Required inputs enforced at submit time: an empty reviewer
+        // or rationale blocks submission and no POST is sent.
+        if (!reviewer || !rationale) {
+          errorBox.textContent =
+            "Reviewer and rationale are both required before submitting.";
+          errorBox.hidden = false;
+          return;
+        }
+
+        var body = {
+          action: mode, // "approve" | "override"
+          final_bucket: bucket,
+          reviewer: reviewer,
+          reviewer_rationale: rationale
+        };
+
+        fetch("/events/" + encodeURIComponent(row.event_id) + "/review", {
+          method: "POST",
+          headers: { "Content-Type": "application/json" },
+          body: JSON.stringify(body)
+        }).then(function (response) {
+          if (!response.ok) {
+            return response.json().then(function (detail) {
+              throw new Error(
+                (detail && detail.message) || ("HTTP " + response.status)
+              );
+            });
+          }
+          hide();
+          // Refresh the queue (and therefore this row, its bucket and
+          // colour) without a full page reload.
+          return loadQueue();
+        }).catch(function (error) {
+          errorBox.textContent = "Review failed: " + error.message;
+          errorBox.hidden = false;
+        });
+      });
+
+      return form;
+    }
+
+    // -- queue table -----------------------------------------------------
+
+    function buildRow(row) {
+      var tr = el("tr", { "data-event-id": row.event_id });
+
+      tr.appendChild(el("td", { text: row.source_id || "" }));
+      tr.appendChild(el("td", { text: row.jurisdiction_name || "" }));
+      tr.appendChild(el("td", { text: row.detected_at || "" }));
+
+      var bucket = displayBucket(row);
+      var bucketClass = BUCKETS.indexOf(bucket) !== -1
+        ? "bucket-" + bucket
+        : "bucket-unknown";
+      // The bucket is colour-coded *and* present as text.
+      tr.appendChild(el("td", { "class": "bucket " + bucketClass, text: bucket }));
+
+      tr.appendChild(el("td", {
+        text: row.confidence !== null && row.confidence !== undefined
+          ? String(row.confidence)
+          : "\u2014"
+      }));
+      tr.appendChild(el("td", {
+        text: isInjection(row) ? "flagged" : "\u2014"
+      }));
+      tr.appendChild(rationaleCell(row.rationale));
+      tr.appendChild(el("td", {}, [
+        el("span", {
+          "class": "status-pill status-" + (row.review_status || "pending"),
+          text: row.review_status || "pending"
+        })
+      ]));
+
+      // Actions cell: Approve + Override controls and their forms.
+      var actionsTd = el("td", { "class": "actions" });
+
+      var hasBucket = BUCKETS.indexOf(bucket) !== -1;
+      var approveForm = reviewForm(row, "approve");
+      var overrideForm = reviewForm(row, "override");
+
+      var approveBtn = el("button", {
+        type: "button",
+        "class": "approve-btn",
+        text: "Approve",
+        "aria-label": "Approve event " + (row.source_id || row.event_id)
+      });
+      var overrideBtn = el("button", {
+        type: "button",
+        "class": "override-btn",
+        text: "Override",
+        "aria-label":
+          "Override bucket for event " + (row.source_id || row.event_id) +
+          " (opens a form with bucket, reviewer and rationale inputs)"
+      });
+
+      if (!hasBucket) {
+        approveBtn.disabled = true;
+        overrideBtn.disabled = true;
+      } else {
+        approveBtn.addEventListener("click", function () {
+          overrideForm.hidden = true;
+          approveForm.hidden = !approveForm.hidden;
+          if (!approveForm.hidden) {
+            approveForm.querySelector("input[name='reviewer']").focus();
+          }
+        });
+        overrideBtn.addEventListener("click", function () {
+          approveForm.hidden = true;
+          overrideForm.hidden = !overrideForm.hidden;
+          if (!overrideForm.hidden) {
+            overrideForm.querySelector("select[name='bucket']").focus();
+          }
+        });
+      }
+
+      actionsTd.appendChild(approveBtn);
+      actionsTd.appendChild(document.createTextNode(" "));
+      actionsTd.appendChild(overrideBtn);
+      actionsTd.appendChild(approveForm);
+      actionsTd.appendChild(overrideForm);
+      tr.appendChild(actionsTd);
+
+      return tr;
+    }
+
+    function renderQueue() {
+      var tbody = document.getElementById("queue-body");
+      tbody.textContent = "";
+
+      state.events.forEach(function (row) {
+        var bucket = displayBucket(row);
+        if (state.filter !== "all" && bucket !== state.filter) {
+          return;
+        }
+        tbody.appendChild(buildRow(row));
+      });
+    }
+
+    function loadQueue() {
+      var status = document.getElementById("queue-status");
+      return fetchJSON("/queue").then(function (data) {
+        if (!Array.isArray(data)) {
+          throw new Error("/queue returned a non-list response");
+        }
+        state.events = data;
+        status.textContent = data.length === 0
+          ? "No events in the queue yet."
+          : data.length + " event(s) in the queue.";
+        renderQueue();
+      }).catch(function (error) {
+        state.events = [];
+        status.textContent = "Failed to load queue: " + error.message;
+        renderQueue();
+      });
+    }
+
+    // -- wiring ----------------------------------------------------------
+
+    var filterSelect = document.getElementById("bucket-filter");
+    filterSelect.addEventListener("change", function () {
+      state.filter = filterSelect.value || "all";
+      renderQueue();
+    });
+
+    loadMetrics();
+    loadQueue();
+  })();
+  </script>
+</body>
+</html>
diff --git a/tests/test_portal.py b/tests/test_portal.py
new file mode 100644
index 0000000..9329cc7
--- /dev/null
+++ b/tests/test_portal.py
@@ -0,0 +1,332 @@
+"""Acceptance tests for the review portal page (REGI-008).
+
+The portal is a static HTML page (``regintel/static/index.html``) served
+by the FastAPI app at ``GET /`` on the same origin as the JSON API. These
+tests exercise the *real running server*: a module-scoped fixture boots
+``scripts/serve.py`` (uvicorn around the FastAPI app in
+:mod:`regintel.api`) on an ephemeral port with ``REGINTEL_DB`` pointed
+at a throwaway SQLite file, and every assertion in this module is made
+against HTTP responses from that live process — not against the module
+object in-process.
+
+HTTP calls use ``httpx`` (the codeline's installed HTTP client —
+``requests`` is not available here).
+
+Covered acceptance criteria:
+
+  * AC1  — ``GET /`` returns 200, ``text/html``, and the page mentions
+           RegIntel plus every bucket name and the Override control.
+  * AC2  — no ``<script src=`` / ``<link href=`` pointing at an http(s)
+           URL (no external CDN dependencies).
+  * AC4  — the bucket filter defaults to 'all' (or an empty value) and
+           offers every bucket as an option, so first load shows every
+           bucket.
+  * AC11 — all assertions run against the real running server.
+
+The remaining browser-rendering criteria (semantic table markup, ARIA,
+keyboard operation, colour tokens) are exercised by the static page
+itself; the server-facing contract above is what Python can verify
+end-to-end here, and it is verified against live HTTP.
+"""
+from __future__ import annotations
+
+import os
+import re
+import shutil
+import socket
+import subprocess
+import sys
+import tempfile
+import time
+from html.parser import HTMLParser
+from pathlib import Path
+from typing import Dict, List, Optional, Tuple
+
+import httpx
+import pytest
+
+REPO_ROOT = Path(__file__).resolve().parents[1]
+STATIC_PAGE = REPO_ROOT / "regintel" / "static" / "index.html"
+
+
+# ---------------------------------------------------------------------------
+# Real-server fixture (module scoped: one uvicorn process for the module)
+# ---------------------------------------------------------------------------
+
+
+def _free_port() -> int:
+    """Ask the OS for a currently unused TCP port."""
+    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
+        sock.bind(("127.0.0.1", 0))
+        return sock.getsockname()[1]
+
+
+@pytest.fixture(scope="module")
+def live_server() -> Tuple[str, Dict[str, str]]:
+    """Boot the real uvicorn server and yield ``(base_url, tmp_dir)``.
+
+    The child process runs ``scripts/serve.py`` (the same entry point a
+    human operator uses) with ``REGINTEL_DB`` pointing at a throwaway
+    SQLite file, so the portal tests never touch a real database.
+    """
+    tmp_dir = Path(tempfile.mkdtemp(prefix="regintel-portal-"))
+    db_path = tmp_dir / "regintel.db"
+
+    port = _free_port()
+    env = dict(os.environ)
+    env["REGINTEL_DB"] = str(db_path)
+    env["PYTHONPATH"] = str(REPO_ROOT) + os.pathsep + env.get("PYTHONPATH", "")
+
+    proc = subprocess.Popen(
+        [sys.executable, str(REPO_ROOT / "scripts" / "serve.py"),
+         "--host", "127.0.0.1", "--port", str(port)],
+        cwd=str(REPO_ROOT),
+        env=env,
+        stdout=subprocess.PIPE,
+        stderr=subprocess.PIPE,
+    )
+
+    base_url = f"http://127.0.0.1:{port}"
+    deadline = time.time() + 20.0
+    last_error: Optional[Exception] = None
+    while time.time() < deadline:
+        if proc.poll() is not None:
+            out, err = proc.communicate()
+            raise RuntimeError(
+                "portal test server exited early:\n"
+                f"stdout={out.decode(errors='replace')}\n"
+                f"stderr={err.decode(errors='replace')}"
+            )
+        try:
+            response = httpx.get(base_url + "/", timeout=2.0)
+            if response.status_code == 200:
+                break
+        except (httpx.HTTPError, OSError) as exc:
+            last_error = exc
+            time.sleep(0.2)
+    else:
+        proc.terminate()
+        raise RuntimeError(
+            f"portal test server never became ready: {last_error}"
+        )
+
+    yield base_url, {"db_path": str(db_path)}
+
+    proc.terminate()
+    try:
+        proc.wait(timeout=5)
+    except subprocess.TimeoutExpired:  # pragma: no cover - defensive
+        proc.kill()
+        proc.wait(timeout=5)
+    shutil.rmtree(tmp_dir, ignore_errors=True)
+
+
+# ---------------------------------------------------------------------------
+# Minimal stdlib HTML inspection (no third-party parser needed)
+# ---------------------------------------------------------------------------
+
+
+class _SelectParser(HTMLParser):
+    """Collect the options (value + selected flag) of <select> elements."""
+
+    def __init__(self) -> None:
+        super().__init__(convert_charrefs=True)
+        self.selects: List[Dict[str, object]] = []
+        self._current: Optional[Dict[str, object]] = None
+        self._in_option = False
+        self._option_value: Optional[str] = None
+        self._option_selected = False
+        self._option_text: List[str] = []
+
+    def handle_starttag(self, tag: str, attrs: List[Tuple[str, Optional[str]]]) -> None:
+        attr_map = dict(attrs)
+        if tag == "select":
+            self._current = {
+                "id": attr_map.get("id"),
+                "name": attr_map.get("name"),
+                "options": [],
+            }
+        elif tag == "option" and self._current is not None:
+            self._in_option = True
+            self._option_value = attr_map.get("value")
+            self._option_selected = "selected" in attr_map
+            self._option_text = []
+
+    def handle_data(self, data: str) -> None:
+        if self._in_option:
+            self._option_text.append(data)
+
+    def handle_endtag(self, tag: str) -> None:
+        if tag == "option" and self._in_option and self._current is not None:
+            options = self._current["options"]
+            assert isinstance(options, list)
+            options.append({
+                "value": self._option_value,
+                "selected": self._option_selected,
+                "text": "".join(self._option_text).strip(),
+            })
+            self._in_option = False
+        elif tag == "select" and self._current is not None:
+            self.selects.append(self._current)
+            self._current = None
+
+
+def _bucket_filter_select(html: str) -> Dict[str, object]:
+    """Return the parsed <select> used as the bucket filter."""
+    parser = _SelectParser()
+    parser.feed(html)
+    for select in parser.selects:
+        options = select.get("options") or []
+        values = {opt["value"] for opt in options if opt["value"] is not None}
+        if {"relevant", "irrelevant", "duplicate", "needs-review"} <= values:
+            return select
+    raise AssertionError(
+        "no <select> offering all four buckets found in the portal page"
+    )
+
+
+# ---------------------------------------------------------------------------
+# AC1 — portal served on the same origin
+# ---------------------------------------------------------------------------
+
+
+def test_portal_served_at_root(live_server: Tuple[str, Dict[str, str]]) -> None:
+    """GET / returns 200 text/html with the RegIntel portal content."""
+    base_url, _ = live_server
+    response = httpx.get(base_url + "/", timeout=10.0)
+
+    assert response.status_code == 200
+    content_type = response.headers.get("content-type", "")
+    assert content_type.startswith("text/html")
+
+    page = response.text
+    for needle in ("RegIntel", "needs-review", "irrelevant", "duplicate",
+                   "Override"):
+        assert needle in page, f"portal page is missing {needle!r}"
+
+
+def test_portal_served_page_matches_static_file(
+    live_server: Tuple[str, Dict[str, str]],
+) -> None:
+    """GET / serves regintel/static/index.html byte-for-byte."""
+    base_url, _ = live_server
+    response = httpx.get(base_url + "/", timeout=10.0)
+    assert response.status_code == 200
+    assert response.text == STATIC_PAGE.read_text(encoding="utf-8")
+
+
+# ---------------------------------------------------------------------------
+# AC2 — no external CDN dependencies
+# ---------------------------------------------------------------------------
+
+
+def test_portal_has_no_external_dependencies(
+    live_server: Tuple[str, Dict[str, str]],
+) -> None:
+    """The served page references no http(s) script/link resources."""
+    base_url, _ = live_server
+    response = httpx.get(base_url + "/", timeout=10.0)
+    page = response.text
+
+    # No <script src= pointing anywhere (same-origin inline JS only).
+    assert not re.search(r"<script[^>]*\bsrc\s*=", page, re.IGNORECASE), (
+        "portal page must not use <script src= (no external scripts)"
+    )
+    # No <link href= pointing at an http(s) URL.
+    for match in re.finditer(
+        r"<link[^>]*\bhref\s*=\s*[\"']([^\"']*)[\"']", page, re.IGNORECASE
+    ):
+        href = match.group(1).strip()
+        assert not re.match(r"^https?://", href, re.IGNORECASE), (
+            f"portal page links to an external resource: {href}"
+        )
+
+
+# ---------------------------------------------------------------------------
+# AC4 — bucket filter defaults to 'all'
+# ---------------------------------------------------------------------------
+
+
+def test_bucket_filter_defaults_to_all(
+    live_server: Tuple[str, Dict[str, str]],
+) -> None:
+    """The filter's default option is 'all' (or empty) so every bucket shows."""
+    base_url, _ = live_server
+    response = httpx.get(base_url + "/", timeout=10.0)
+    assert response.status_code == 200
+
+    select = _bucket_filter_select(response.text)
+    options = select["options"]
+    assert isinstance(options, list) and options, "filter has no options"
+
+    selected = [opt for opt in options if opt["selected"]]
+    if selected:
+        # Exactly one explicitly selected option, and it is the 'all'
+        # (or empty-value) option that shows every bucket.
+        assert len(selected) == 1
+        assert selected[0]["value"] in ("all", "", None)
+    else:
+        # No explicit selection: the first option is the default per
+        # HTML semantics — it must be the show-everything option.
+        first = options[0]
+        assert first["value"] in ("all", "", None)
+
+    # Every bucket is offered as a filter choice.
+    values = {
+        opt["value"]
+        for opt in options
+        if isinstance(opt["value"], str) and opt["value"]
+    }
+    assert {"relevant", "irrelevant", "duplicate", "needs-review"} <= values
+
+
+# ---------------------------------------------------------------------------
+# Same-origin sanity: the JSON API is reachable on the same server
+# ---------------------------------------------------------------------------
+
+
+def test_queue_endpoint_on_same_origin(
+    live_server: Tuple[str, Dict[str, str]],
+) -> None:
+    """GET /queue answers on the same origin the page is served from."""
+    base_url, _ = live_server
+    response = httpx.get(base_url + "/queue", timeout=10.0)
+    assert response.status_code == 200
+    assert response.headers.get("content-type", "").startswith(
+        "application/json"
+    )
+    assert response.json() == []  # fresh throwaway DB, no events yet
+
+
+def test_metrics_endpoint_on_same_origin(
+    live_server: Tuple[str, Dict[str, str]],
+) -> None:
+    """GET /metrics answers on the same origin the page is served from."""
+    base_url, _ = live_server
+    response = httpx.get(base_url + "/metrics", timeout=10.0)
+    assert response.status_code == 200
+    body = response.json()
+    assert body["events"] == 0
+    assert body["cost_per_event_usd"] == 0
+
+
+# ---------------------------------------------------------------------------
+# AC9 (server side of the story) — the page's data endpoints tolerate an
+# empty database, which is the state the portal renders on first load.
+# ---------------------------------------------------------------------------
+
+
+def test_empty_db_renders_clean_api_state(
+    live_server: Tuple[str, Dict[str, str]],
+) -> None:
+    """With an empty DB both /queue and /metrics return well-formed 200s."""
+    base_url, _ = live_server
+    queue = httpx.get(base_url + "/queue", timeout=10.0)
+    metrics = httpx.get(base_url + "/metrics", timeout=10.0)
+    assert queue.status_code == 200 and queue.json() == []
+    assert metrics.status_code == 200 and metrics.json()["counts"] == {
+        "relevant": 0,
+        "irrelevant": 0,
+        "duplicate": 0,
+        "needs-review": 0,
+    }
